3\u0441\u043a (\u043e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e-\u0430\u043b\u0444\u0430\u0432\u0438\u0442, `[...]` \u0441 \u0438\u0437\u043e\u0442\u043e\u043f\u043e\u043c/\u0437\u0430\u0440\u044f\u0434\u043e\u043c/H-\u0441\u0447\u0451\u0442\u043e\u043c, \u0441\u0432\u044f\u0437\u0438 `- = # / \\ : .`, \u0432\u0435\u0442\u043a\u0438 `()`, \u0437\u0430\u043c\u044b\u043a\u0430\u043d\u0438\u044f `%nn`). \u0421\u0442\u0435\u0440\u0435\u043e (`@`, `/`,`\\`) \u043f\u0430\u0440\u0441\u0438\u043c \u0438 **\u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u043c** \u2014 \u043d\u0430 2D-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442, \u0444\u0430\u043a\u0442 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0432 \u043b\u043e\u0433.\n- SDF: \u043f\u0430\u0440\u0441\u0435\u0440 header/counts/atom-block/bond-block/properties \u2192 \u0442\u043e\u0442 \u0436\u0435 molgraph, \u0447\u0442\u043e \u0438 \u0438\u0437 SMILES, \u043f\u043b\u044e\u0441 \u043f\u0440\u043e\u043a\u0438\u0434\u043a\u0430 \u043f\u043e\u043b\u0435\u0439 (`_CHEMBL_ID`, `_MAXCD_CONVERSIONFAILED` \u0438 \u0442.\u043f.).\n- \u041c\u0443\u043b\u044c\u0442\u0438\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u043d\u044b\u0435 \u0437\u0430\u043f\u0438\u0441\u0438 (`.`) \u2014 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e:largest-fragment (\u0441\u043e \u0441\u0447\u0451\u0442\u043e\u043c \u0438\u0441\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u044b\u0445 \u043d\u0435-\u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043e\u0432 \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u0442\u043e\u043b\u0431\u0435\u0446).\n- **\u041a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 failure ledger** (\u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u0442\u0430\u043a\u0441\u043e\u043d\u043e\u043c\u0438\u044f \u0434\u043b\u044f SMILES \u0438 SDF): `EMPTY / BAD_CHAR / VALENCE / UNMATCHED_RING / NONCONNECTED / MISSING_FIELD / PARSE_FAIL`; \u043d\u0430 \u0432\u044b\u0445\u043e\u0434\u0435 \u0434\u043e\u043b\u044f \u043d\u0435\u0443\u0441\u043f\u0435\u0445\u043e\u0432 \u043f\u043e \u043a\u043b\u0430\u0441\u0441\u0430\u043c \u0438 \u0441\u044b\u0440\u043e\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0431\u0438\u0442\u044b\u0445 \u0437\u0430\u043f\u0438\u0441\u0435\u0439.\n\n**B. \u0414\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u2014 \u0447\u0438\u0441\u0442\u044b\u0439 Python \u043f\u043e\u0432\u0435\u0440\u0445 molgraph.**\n- \u0410\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c: \u043f\u043e\u0438\u0441\u043a \u043a\u043e\u043b\u0435\u0446 (\u0446\u0438\u043a\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0447\u0438\u0441\u043b\u043e + SSSR-\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0438 DFS), \u043f\u0435\u0440\u0446\u0435\u043f\u0446\u0438\u044f \u043f\u043e \u0425\u044e\u043a\u043a\u0435\u043b\u044e; H-\u043f\u043e-\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438, \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434.\n- MW (\u0441\u0440\u0435\u0434\u043d\u0438\u0435 \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043c\u0430\u0441\u0441\u044b), numHeavyAtoms, \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434, \u043a\u043e\u043b\u044c\u0446\u0430 (\u043e\u0431\u0449\u0435\u0435/aromatic), \u0447\u0438\u0441\u043b\u043e \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0441\u0432\u044f\u0437\u0435\u0439.\n- HBD/HBA: \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u044e\u0449\u0438\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f RDKit Lipinski (OH/NH \u0434\u043e\u043d\u043e\u0440\u044b; N/O \u0430\u043a\u0446\u0435\u043f\u0442\u043e\u0440\u044b \u0441 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f\u043c\u0438 \u0430\u043c\u0438\u0434\u043e\u0432/\u043f\u0438\u0440\u0438\u0434\u0438\u043d\u043e\u0432\u044b\u0445 N-\u0442\u0438\u043f\u043e\u0432).\n- TPSA: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0432\u043a\u043b\u0430\u0434\u044b\u0448\u0435\u0439 Ertl (Topliss) ~60 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u0445 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432, \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u044b\u0445 \u043a\u0430\u043a \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043f\u043e\u0434\u0433\u0440\u0430\u0444\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 (\u0443 \u043d\u0430\u0441 \u0436\u0435 \u0435\u0441\u0442\u044c \u0441\u0432\u043e\u0439 isomorphism) \u2014 \u043d\u0435 \u00ab\u0443\u0433\u0430\u0434\u044b\u0432\u0430\u043d\u0438\u0435\u00bb, \u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u044b.\n- logP: \u0430\u0442\u043e\u043c-\u0432\u043a\u043b\u0430\u0434\u043e\u0432\u043e\u0439 XLogP/Wildman\u2013Crippen-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0442\u0438\u043f\u043e\u0432 (\u0443\u043f\u0440\u043e\u0449\u0451\u043d\u043d\u044b\u0439, \u0441 \u044f\u0432\u043d\u043e \u0437\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0441\u043f\u0438\u0441\u043a\u043e\u043c \u0442\u0438\u043f\u043e\u0432).\n- Rotatable bonds: \u043f\u043e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e RDKit (`NumRotatableBonds` strict: \u043d\u0435 \u0432 \u043a\u043e\u043b\u044c\u0446\u0435, \u043e\u0431\u0430 \u043a\u043e\u043d\u0446\u0430 \u043d\u0435 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u044b, \u043d\u0435 \u0430\u043c\u0438\u0434\u043d\u0430\u044f C\u2013N, \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u0430\u044f \u0441\u0432\u044f\u0437\u044c).\n- pKa: **\u043e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u043e \u0437\u0430 \u0441\u043a\u043e\u0443\u043f\u043e\u043c** \u2014 \u0447\u0435\u0441\u0442\u043d\u043e \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u043c, \u0447\u0442\u043e \u043e\u0444\u043b\u0430\u0439\u043d-\u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e\u0439 \u0442\u043e\u0447\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 \u043d\u0435\u0442; \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u00ab\u043a\u0438\u0441\u043b\u043e\u0442\u043d\u044b\u0435/\u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0446\u0435\u043d\u0442\u0440\u044b + \u0441\u0447\u0451\u0442\u0447\u0438\u043a\u00bb \u0432\u043c\u0435\u0441\u0442\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f. \u041e\u043f\u0446\u0438\u044f \u0441\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f \u043f\u043e \u0432\u0430\u0448\u0435\u043c\u0443 \u0440\u0435\u0448\u0435\u043d\u0438\u044e.\n\n**C. \u0410\u043d\u0430\u043b\u0438\u0437.**\n- \u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 \u0432 SQLite (\u0441\u0442\u0440\u0438\u043c\u0438\u043d\u0433, \u0431\u0435\u0437 pandas) + CSV-\u0432\u044b\u0433\u0440\u0443\u0437\u043a\u0430.\n- \u0420\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f: `statistics.quantiles` + bincount \u0432\u0440\u0443\u0447\u043d\u0443\u044e; \u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0442\u0435\u043a\u0441\u0442\u043e\u043c \u0438\u043b\u0438 PNG \u0447\u0435\u0440\u0435\u0437 PIL.\n- \u041a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438: `statistics.correlation` (\u041f\u0438\u0440\u0441\u043e\u043d) \u043f\u043e \u043f\u043e\u043f\u0430\u0440\u043d\u043e \u043f\u043e\u043b\u043d\u044b\u043c \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f\u043c; \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u0421\u043f\u0438\u0440\u043c\u0435\u043d \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u043d\u0436\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435.\n- \u0424\u0438\u043b\u044c\u0442\u0440\u044b: Lipinski (MW\u2264500, logP\u22645, HBD\u22645, HBA\u226410), Veber (TPSA\u2264140 \u00c5\u00b2, RB\u226410) \u2014 \u043f\u043e\u0440\u043e\u0433\u0438 \u0438 \u00ab\u0447\u0438\u0441\u043b\u043e \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439\u00bb \u043a\u0430\u043a \u0441\u0442\u043e\u043b\u0431\u0446\u044b, \u0447\u0442\u043e\u0431\u044b \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0431\u044b\u043b\u0430 \u0432\u0438\u0434\u043d\u0430.\n- \u0413\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438: \u0433\u0440\u0443\u043f\u043f-\u0431\u0430\u0439 \u043f\u043e `source`/`class`/`standard` (\u0435\u0441\u043b\u0438 \u043f\u043e\u043b\u044f \u0435\u0441\u0442\u044c) \u0441 \u043c\u0435\u0434\u0438\u0430\u043d\u0430\u043c\u0438 \u0438 \u0440\u0430\u0437\u0431\u0440\u043e\u0441\u043e\u043c; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u043e\u043b\u0435\u0439 \u043f\u0440\u043e\u0445\u043e\u0434\u043e\u0432 \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u0433\u0440\u0443\u043f\u043f\u0430\u043c\u0438.\n- \u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043a\u0430\u043a \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u0438\u0441\u0445\u043e\u0434\u044b \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432 \u043f\u0440\u0438 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0438 \u043f\u043e\u0440\u043e\u0433\u0430 logP/TPSA \u043d\u0430 \u00b110% (\u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e logP \u0443 \u043d\u0430\u0441 \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0451\u043d\u043d\u044b\u0439).\n\n**D. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438/\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f (\u0433\u043b\u0430\u0432\u043d\u043e\u0435, \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0434\u0438\u0437\u0430\u0439\u043d \u043d\u0430\u0443\u0447\u043d\u044b\u043c).**\n1. **Unit-\u0442\u0435\u0441\u0442\u044b \u0433\u0440\u0430\u0444\u0430** (unittest): \u043a\u043e\u043b\u044c\u0446\u0435\u0432\u044b\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b, \u0437\u0430\u0440\u044f\u0436\u0435\u043d\u043d\u044b\u0435/\u0438\u043e\u043d\u043d\u044b\u0435 \u0444\u043e\u0440\u043c\u044b, \u0433\u0430\u043b\u043e\u0433\u0435\u043d\u044b, `.`-\u0440\u0430\u0437\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u0441\u043c\u0435\u0441\u0438.\n2. **\u0421\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u043f\u0430\u043d\u0435\u043b\u044c** \u0441 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438: \u0430\u0441\u043f\u0438\u0440\u0438\u043d MW 180.16, \u043a\u043e\u0444\u0435\u0438\u043d 194.19, \u0433\u043b\u044e\u043a\u043e\u0437\u0430 180.16, \u044d\u0442\u0430\u043d\u043e\u043b 46.07, ATP 507.18, \u0438\u0431\u0443\u043f\u0440\u043e\u0444\u0435\u043d 206.28 \u2014 \u0434\u043e\u043f\u0443\u0441\u043a\u0438: MW \u00b10.05, HBD/HBA \u00b10, TPSA \u00b12 \u00c5\u00b2, logP \u00b10.5\u20130.7, RB \u00b11. \u041f\u043e\u0440\u043e\u0433\u0438 PASS/FAIL \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430.\n3. **\u0421\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u043f\u0430\u0440\u0441\u0435\u0440\u043e\u0432:** \u0434\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b, \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0438 \u043a\u0430\u043a SDF, \u0438 \u043a\u0430\u043a SMILES (\u0433\u043e\u0442\u043e\u0432\u0438\u043c \u043c\u0438\u043d\u0438-\u043a\u043e\u0440\u043f\u0443\u0441 ~10\u201320 \u0437\u0430\u043f\u0438\u0441\u0435\u0439), \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u0443\u0442\u0435\u0439 \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0442\u044c \u043f\u043e\u0431\u0438\u0442\u043e\u0432\u043e/\u00b1EPS \u2014 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0431\u0435\u0437 \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u0441\u043e\u0444\u0442\u0430.\n4. **Sanity-\u0433\u0440\u0430\u043d\u0438\u0446\u044b:** MW>0, TPSA\u22650, 0\u2264HBD\u2264HBA-\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e, RB\u22650, |\u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0440\u044f\u0434|\u22645 \u043a\u0430\u043a \u0444\u043b\u0430\u0433-\u0432\u044b\u0431\u0440\u043e\u0441.\n5. **Headline-\u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430:** \u0434\u043e\u043b\u044f \u043d\u0435\u0443\u0441\u043f\u0435\u0448\u043d\u044b\u0445 \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u043e\u0432 \u043f\u043e \u043a\u043b\u0430\u0441\u0441\u0430\u043c, \u0434\u043e\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b, \u043f\u043e\u043f\u0430\u0432\u0448\u0438\u0445 \u0432 \u22651 \u0438\u0441\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u044b\u0439 \u043a\u043b\u0430\u0441\u0441 (\u043c\u0435\u0442\u0438/\u0440\u0435\u0434\u043a\u0438\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b/\u0434\u0438\u0441\u043e\u043d\u0435\u043a\u0442\u044b).\n6. **\u0412\u043d\u0435\u0448\u043d\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c (\u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0441\u0435\u0442\u044c):** \u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u0430\u044f \u0441\u0432\u0435\u0440\u043a\u0430 \u0441 PubChem REST / \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0439 \u043a\u043e\u043f\u0438\u0435\u0439 ChEMBL; \u0431\u0435\u0437 \u0441\u0435\u0442\u0438 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u043c \u043a\u0430\u043a \u00ab\u0437\u0430\u0434\u0435\u043b\u00bb, \u043d\u0435 \u043a\u0430\u043a \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442.\n\n**\u041e\u0436\u0438\u0434\u0430\u0435\u043c\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c fallback \u043f\u0440\u043e\u0442\u0438\u0432 RDKit (\u0447\u0435\u0441\u0442\u043d\u043e, \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b/\u043e\u0446\u0435\u043d\u043e\u043a, \u043d\u0435 \u0438\u0437 \u0437\u0430\u043c\u0435\u0440\u043e\u0432 \u0437\u0434\u0435\u0441\u044c):**\n- MW: \u0442\u043e\u0447\u043d\u043e (<0.01% \u043f\u0440\u0438 \u0442\u043e\u0439 \u0436\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u0435 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441). HBD/HBA: \u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043f\u0440\u0438 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0445 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u0445 (\u00b11 \u043d\u0430 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u0430\u0445/\u044d\u043a\u0437\u043e\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 N). TPSA: \u00b11\u20132 \u00c5\u00b2 \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u044b. logP: MAE \u22480.4\u20130.7 \u043b\u043e\u0433-\u0435\u0434\u0438\u043d\u0438\u0446 \u0434\u043b\u044f drug-like, \u0445\u0443\u0436\u0435 \u043d\u0430 \u0432\u044b\u0431\u0440\u043e\u0441\u0430\u0445 (\u043f\u043e\u043b\u0438\u0446\u0438\u043a\u043b\u044b, \u0433\u0435\u0442\u0435\u0440\u043e\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u0438) \u2014 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 logP \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432 \u0441\u0432\u044f\u0437\u043a\u0435 \u0441 \u0430\u043d\u0430\u043b\u0438\u0437\u043e\u043c \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438. Rotatable bonds: \u0442\u0438\u043f\u0438\u0447\u043d\u043e \u00b11 \u0438\u0437-\u0437\u0430 \u043a\u0440\u0430\u0435\u0432\u044b\u0445 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439. \u0414\u043e\u043b\u044f \u043d\u0435\u0443\u0441\u043f\u0435\u0448\u043d\u043e\u0433\u043e \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430 \u0434\u043b\u044f \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0445 SMILES ~1\u20135%, \u0432\u044b\u0448\u0435 \u0434\u043b\u044f \u00ab\u0441\u044b\u0440\u044b\u0445\u00bb \u0437\u0430\u043f\u0438\u0441\u0435\u0439 \u0438\u0437 \u0441\u043a\u0440\u0438\u043d\u0438\u043d\u0433\u043e\u0432\u044b\u0445 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a, \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0432\u044b\u0448\u0435 \u0434\u043b\u044f \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432/\u043d\u0435\u043e\u0440\u0433\u0430\u043d\u0438\u043a\u0438 (\u0438\u0445 \u0432\u044b\u043d\u043e\u0441\u0438\u043c \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044e, \u0430 \u043d\u0435 \u00ab\u0447\u0438\u043d\u0438\u043c\u00bb).\n\n## 3) \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u044f\u0441\u043d\u043e\u0441\u0442\u0438\n\n**\u0424\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f/\u0444\u0430\u043a\u0442\u044b (\u043d\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f):** \u0437\u0430\u0434\u0430\u0447\u0430 design-only (`track.md`), \u0441\u0435\u0442\u044c \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u0430, RDKit/numpy/pandas \u043d\u0435\u0442, \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u0432 `/workspace` \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, \u043d\u0430 NFS \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e ~2.1 \u0413\u0411, 224 CPU/~2 \u0422\u0411 RAM.\n\n**\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u044f\u0432\u043d\u044b\u0435):**\n- \u0414\u0430\u0442\u0430\u0441\u0435\u0442 **\u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d**: \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435, \u0444\u043e\u0440\u043c\u0430\u0442, \u043e\u0431\u044a\u0451\u043c, schema, \u044f\u0437\u044b\u043a \u0437\u0430\u043f\u0438\u0441\u0435\u0439 \u2014 \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b, \u043d\u0435 \u0434\u043e\u0434\u0443\u043c\u0430\u043d\u044b.\n- \u0421\u0447\u0438\u0442\u0430\u0435\u043c, \u0447\u0442\u043e \u0437\u0430\u043f\u0438\u0441\u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442 SMILES \u0438\u043b\u0438 molgraph (SDF); \u0435\u0441\u043b\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442 \u0432\u043e\u0432\u0441\u0435, \u043f\u0440\u043e\u0433\u043e\u043d \u043f\u043e\u0434\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043a\u0443\u0440\u0438\u0440\u0443\u0435\u043c\u044b\u043c \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u043c \u043a\u043e\u0440\u043f\u0443\u0441\u043e\u043c ~100\u2013200 SMILES \u0441 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 (\u044d\u0442\u043e \u0443\u0436\u0435 \u00ab\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f\u00bb, \u0430 \u043d\u0435 \u00ab\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0443\u00bb).\n- 2D-\u0443\u0440\u043e\u0432\u0435\u043d\u044c: \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u044b/\u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435/\u0441\u043e\u043b\u044c\u0432\u0430\u0442\u044b \u043d\u0435 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0443\u044e\u0442\u0441\u044f (\u0437\u0430\u044f\u0432\u043b\u044f\u0435\u043c \u043a\u0430\u043a \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435).\n- \u0421\u0440\u0435\u0434\u043d\u0438\u0435 \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043c\u0430\u0441\u0441\u044b (\u043d\u0435 \u043c\u043e\u043d\u043e\u0438\u0437\u043e\u0442\u043e\u043f\u043d\u044b\u0435), \u0435\u0441\u043b\u0438 \u043d\u0435 \u0441\u043a\u0430\u0436\u0435\u0442\u0435 \u0438\u043d\u0430\u0447\u0435.\n\n**\u041d\u0435\u044f\u0441\u043d\u043e\u0441\u0442\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0443\u0436\u043d\u043e \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0432\u0430\u043c (3 \u0432\u043e\u043f\u0440\u043e\u0441\u0430, \u0431\u044e\u0434\u0436\u0435\u0442 6):**\n1. \u0414\u0430\u0442\u0430\u0441\u0435\u0442: \u0431\u0443\u0434\u0435\u0442 \u043b\u0438 \u043f\u043e\u0434\u043b\u043e\u0436\u0435\u043d \u0444\u0430\u0439\u043b (\u043a\u0430\u043a\u043e\u0439 \u0444\u043e\u0440\u043c\u0430\u0442/\u043e\u0431\u044a\u0451\u043c/schema) \u2014 \u0438\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u043c \u043d\u0430 \u043a\u0443\u0440\u0438\u0440\u0443\u0435\u043c\u043e\u043c \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u043c \u043a\u043e\u0440\u043f\u0443\u0441\u0435?\n2. pKa: \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u043c \u0432 \u0441\u043a\u043e\u0443\u043f\u0435 (\u0441 \u0447\u0435\u0441\u0442\u043d\u043e\u0439 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439 \u043f\u0440\u043e \u043d\u0438\u0437\u043a\u0443\u044e \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c) \u0438\u043b\u0438 \u0432\u044b\u0447\u0451\u0440\u043a\u0438\u0432\u0430\u0435\u043c?\n3. \u0424\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u044b\u0432\u043e\u0434: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 + \u043e\u0442\u0447\u0451\u0442 \u0441 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u043c\u0438/\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u044f\u043c\u0438/\u0444\u0438\u043b\u044c\u0442\u0440\u0430\u043c\u0438, \u0438\u043b\u0438 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442 \u043d\u0430 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u043e\u043d\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c (\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c fallback \u043f\u0440\u043e\u0442\u0438\u0432 RDKit)?\n\n**\u041a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 (\u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f):** \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0435 SMILES+SDF-\u043f\u0430\u0440\u0441\u0435\u0440\u043e\u0432 \u0438 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 ~1.5\u20133k \u0441\u0442\u0440\u043e\u043a \u0447\u0438\u0441\u0442\u043e\u0433\u043e Python \u2014 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u0441\u0435\u0441\u0441\u0438\u0439; runtime \u043d\u0430 10\u2074\u201310\u2075 \u0437\u0430\u043f\u0438\u0441\u0435\u0439 \u2014 \u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u044f\u0434\u0440\u0435, \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u0438\u0442\u0441\u044f \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e (`multiprocessing`), \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438 \u2014 \u0434\u0435\u0441\u044f\u0442\u043a\u0438 \u041c\u0411 \u043d\u0430 worker; \u0434\u0438\u0441\u043a \u2014 \u0434\u0435\u0440\u0436\u0438\u043c <500 \u041c\u0411 \u0438\u0437-\u0437\u0430 2.1 \u0413\u0411 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e.\n\n\u0413\u043e\u0442\u043e\u0432 \u0440\u0430\u0437\u0432\u0451\u0440\u043d\u0443\u0442\u044c \u043f\u043e\u043b\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u043e\u0441\u043b\u0435 \u0432\u0430\u0448\u0435\u0433\u043e approve; \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b \u043a\u0440\u043e\u043c\u0435 \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u043f\u0440\u043e\u0432\u0435\u0440\u043e\u043a \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f (\u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u043f\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0443 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u043e\u0441\u044c):\n- `ls -laR /workspace` \u2192 \u0442\u043e\u043b\u044c\u043a\u043e `task.json` (378 B); `file task.json` \u2192 \"JSON text data\"; \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435: question/context/documents.track.md (\"Design-only task; repositories and compute are not required\").\n- `find / -xdev` \u043f\u043e `*.sdf *.smi *.mol2 *.smiles *.smi.gz` \u2192 \u043f\u0443\u0441\u0442\u043e. `/data`, `/datasets`, `/input`, `/opt` \u2014 \u043d\u0435\u0442.\n- \u0418\u043c\u043f\u043e\u0440\u0442-\u0442\u0435\u0441\u0442: FAIL rdkit, openbabel, numpy, pandas, scipy, matplotlib, sklearn, pyarrow, networkx, Bio, lxml, svgwrite; OK yaml 6.0.3, requests 2.32.5, PIL 12.1.1, sqlite3, csv, json, statistics, graphlib, fractions, diff