30\u0440\u044f\u0434\u044b) \u0434\u0430\u0451\u0442 *\u043c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u043e \u043d\u0435\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0435* \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b, \u0430 \u043d\u0435 exception. \u042d\u0442\u043e \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043e\u0448\u0438\u0431\u043a\u0438, \u0438 \u043e\u043d \u043d\u0435 \u043b\u043e\u0432\u0438\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u043d\u044b\u043c\u0438 \u0442\u0435\u0441\u0442\u0430\u043c\u0438.\n2. **\u0412\u0440\u0443\u0447\u043d\u0443\u044e \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b\u0435 \u0442\u0430\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u0432\u043a\u043b\u0430\u0434\u044b** (TPSA-\u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b Ertl/Topliss, \u0442\u0438\u043f\u044b \u0430\u0442\u043e\u043c\u043e\u0432 \u0434\u043b\u044f logP). \u041e\u043f\u0435\u0447\u0430\u0442\u043a\u0430/\u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u044b\u0439 \u043f\u0430\u0442\u0442\u0435\u0440\u043d \u2192 \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0432\u0441\u044f\u043a\u043e\u0433\u043e \u0441\u0438\u0433\u043d\u0430\u043b\u0430 \u043e\u0431 \u043e\u0448\u0438\u0431\u043a\u0435.\n\n\u0421\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435, \u0437\u0430\u0434\u0430\u044e\u0449\u0435\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0432\u0441\u0435\u0433\u043e \u0434\u0438\u0437\u0430\u0439\u043d\u0430: **\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u0434\u0435\u043b\u044f\u0442\u0441\u044f \u043d\u0430 \u0434\u0432\u0430 \u0441\u043e\u0440\u0442\u0430**, \u0438 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u0438\u0445 \u0432 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0430\u0445 \u043d\u0435\u043b\u044c\u0437\u044f (\u00a73 Tier A / Tier B). \u0412\u043d\u0435\u0448\u043d\u0435\u0439 \u0442\u043e\u0447\u043a\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435\u0442 (\u00a77).\n\n---\n\n## 2. Input / ingestion\n\n**\u0424\u043e\u0440\u043c\u0430\u0442-\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u0432\u0445\u043e\u0434** (\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0437\u0430\u043f\u0443\u0441\u043a\u0430): CSV/TSV \u0441\u043e SMILES-\u043a\u043e\u043b\u043e\u043d\u043a\u043e\u0439, `.smi`, SDF. \u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u2014 \u0444\u043e\u0440\u043c\u0430\u0442 \u043d\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f, \u0430 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f.\n\n**Format diagnostics (\u0434\u043e \u043b\u044e\u0431\u043e\u0439 \u0445\u0438\u043c\u0438\u0438, \u0434\u0435\u0448\u0451\u0432\u044b\u0439 pass):** magic-bytes \u2192 gzip/zstd/plain; encoding probe (utf-8 strict \u2192 latin-1 fallback, \u0444\u0430\u043a\u0442 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f); delimiter sniff \u043f\u043e \u043f\u0435\u0440\u0432\u044b\u043c N \u0441\u0442\u0440\u043e\u043a\u0430\u043c; header detection; \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0441\u0442\u0440\u043e\u043a \u0438 \u043f\u043e\u043b\u0435\u0439; \u0434\u0435\u0442\u0435\u043a\u0442 \u00ab\u043e\u0434\u043d\u0430 \u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u0431\u0435\u0437 \u0437\u0430\u043f\u044f\u0442\u044b\u0445\u00bb \u2192 smi-\u0440\u0435\u0436\u0438\u043c. \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 machine-readable `ingest_manifest.json` (\u0444\u043e\u0440\u043c\u0430\u0442, encoding, \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c, \u0438\u043c\u044f SMILES-\u043a\u043e\u043b\u043e\u043d\u043a\u0438, \u0447\u0438\u0441\u043b\u043e \u0441\u0442\u0440\u043e\u043a). \u041e\u043d \u0436\u0435 \u2014 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438.\n\n**\u0415\u0434\u0438\u043d\u044b\u0439 molgraph-\u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441.** SMILES-\u043f\u0430\u0440\u0441\u0435\u0440 \u0438 SDF-\u043f\u0430\u0440\u0441\u0435\u0440 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442 \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0442\u0438\u043f: `Atom{idx, el, charge, h_count, is_aromatic, isotope, in_ring_sizes[]}`, `Bond{i, j, order, aromatic}`, `fragments[]`, `parse_provenance`. \u0412\u0441\u0435 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u2014 \u0447\u0438\u0441\u0442\u044b\u0435 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u043e\u0442 molgraph \u0438 **\u043d\u0435 \u0437\u043d\u0430\u044e\u0442 \u043e \u0432\u0445\u043e\u0434\u043d\u043e\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435**. \u042d\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c SDF\u2194SMILES (\u00a74.3) \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0442 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0434\u0432\u0443\u0445 \u043f\u0443\u0442\u0435\u0439.\n- SMILES: \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440 + \u0440\u0435\u043a\u0443\u0440\u0441\u0438\u0432\u043d\u044b\u0439 \u0441\u043f\u0443\u0441\u043a; \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c: \u043e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e-\u0430\u043b\u0444\u0430\u0432\u0438\u0442, `[...]` (\u0438\u0437\u043e\u0442\u043e\u043f, \u0437\u0430\u0440\u044f\u0434, H-\u0441\u0447\u0451\u0442), \u0441\u0432\u044f\u0437\u0438 `- = # : / \\ .`, \u0432\u0435\u0442\u043a\u0438, \u043a\u043e\u043b\u044c\u0446\u0430 `%nn`, `*` (\u043a\u0430\u043a wildcard \u2192 OUT_OF_POLICY). \u0421\u0442\u0435\u0440\u0435\u043e (`@`, `@@`, `/`, `\\`) \u043f\u0430\u0440\u0441\u0438\u0442\u0441\u044f \u0438 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0441 \u0437\u0430\u043f\u0438\u0441\u044c\u044e \u0432 \u043b\u043e\u0433 (2D-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u043e\u0442 \u043d\u0435\u0433\u043e \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u044f\u0442).\n- SDF: V2000 counts-line \u2192 atom block \u2192 bond block \u2192 `M  END`; \u043f\u0440\u043e\u043a\u0438\u0434\u043a\u0430 property-fields \u0432 \u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u0435. V3000 \u2014 \u044f\u0432\u043d\u044b\u0439 \u043e\u0442\u043a\u0430\u0437 \u0441 \u043a\u043e\u0434\u043e\u043c ledger, \u0430 \u043d\u0435 \u0442\u0438\u0445\u0430\u044f \u043f\u043e\u0440\u0447\u0430.\n\n**\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u043e \u043c\u0443\u043b\u044c\u0442\u0438\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u043d\u044b\u043c \u0437\u0430\u043f\u0438\u0441\u044f\u043c.** \u041f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e `largest_fragment` \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432; \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e \u043f\u0438\u0448\u0443\u0442\u0441\u044f `n_fragments`, `n_heavy_fragments`, `n_atoms_dropped`, `salt_formula`. \u041f\u0440\u0430\u0432\u0438\u043b\u043e \u043e\u0434\u043d\u043e\u0437\u043d\u0430\u0447\u043d\u043e: ties \u2192 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 \u0441 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u043c \u0438\u043d\u0434\u0435\u043a\u0441\u043e\u043c \u0430\u0442\u043e\u043c\u0430, \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d. \u0417\u0430\u043f\u0438\u0441\u0438 \u0441 >1 \u0442\u044f\u0436\u0451\u043b\u044b\u043c \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043e\u043c \u043f\u043e\u043c\u0435\u0447\u0430\u044e\u0442\u0441\u044f `MULTI_HEAVY` \u0438 **\u043d\u0435 \u0432\u0445\u043e\u0434\u044f\u0442** \u0432 headline-\u043c\u0435\u0442\u0440\u0438\u043a\u0438 (\u043d\u043e \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u00ab\u043f\u043b\u043e\u0445\u0438\u043c\u0438\u00bb \u2014 \u044d\u0442\u043e \u0438\u043d\u043e\u0439 \u0440\u0435\u0436\u0438\u043c).\n\n**Failure ledger \u2014 \u0442\u0430\u043a\u0441\u043e\u043d\u043e\u043c\u0438\u044f \u0441 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0432\u044b\u0445\u043e\u0434\u0430\u043c\u0438.** \u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435: \u00ab\u043d\u0435 \u043f\u0430\u0440\u0441\u0438\u0442\u0441\u044f\u00bb \u0438 \u00ab\u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0438\u043b\u0430\u0441\u044c, \u043d\u043e \u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u0432\u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438\u00bb \u2014 **\u0434\u0432\u0430 \u0440\u0430\u0437\u043d\u044b\u0445 \u0432\u044b\u0445\u043e\u0434\u0430**, \u0438 \u0441\u0432\u043e\u0434\u0438\u0442\u044c \u0438\u0445 \u0432 \u043e\u0434\u043d\u0443 \u0434\u043e\u043b\u044e \u043d\u0435\u0443\u0434\u0430\u0447 \u043d\u0435\u043b\u044c\u0437\u044f (\u0438\u043d\u0430\u0447\u0435 headline-\u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u0432\u0440\u0451\u0442 \u0432 \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b: \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0438 \u0441 \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c\u0438 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u00ab\u0441\u043b\u043e\u043c\u0430\u043d\u043d\u044b\u043c\u0438\u00bb, \u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0431\u0438\u0442\u044b\u0435 SMILES \u0442\u043e\u043d\u0443\u0442 \u0432 \u0448\u0443\u043c\u0435).\n\n| \u041a\u043e\u0434 | \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 | \u0422\u044f\u043d\u0435\u0442 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b? | \u0412\u0445\u043e\u0434\u0438\u0442 \u0432 parse-failure denominator? |\n|---|---|---|---|\n| `OK` | \u043f\u043e\u043b\u043d\u044b\u0439 \u0433\u0440\u0430\u0444, \u0432\u0441\u0451 \u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u0445 | \u0434\u0430 | \u2014 |\n| `E_INPUT` | \u043f\u0443\u0441\u0442\u043e\u0435 \u043f\u043e\u043b\u0435 / \u043d\u0435\u0442 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 / \u043d decodable | \u043d\u0435\u0442 | \u0434\u0430 (data hygiene) |\n| `E_GRAMMAR` | \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0430\u044f \u0432\u0435\u0442\u043a\u0430, \u043d\u0435\u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0435/\u043d\u0435\u0437\u0430\u043c\u043a\u043d\u0443\u0442\u043e\u0435 \u043a\u043e\u043b\u044c\u0446\u043e, \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u0441\u0438\u043c\u0432\u043e\u043b, `M  END` \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, V3000 | \u043d\u0435\u0442 | **\u0434\u0430 (headline parse-failure)** |\n| `E_VALENCE` | \u0433\u0440\u0430\u0444 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d, \u043d\u043e \u0441\u0430\u043d\u0438\u0442\u0430\u0439\u0437 \u043d\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 (\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c/\u0430\u0440\u043e\u043c\u0430\u0442\u0438\u043a\u0430) | \u043d\u0435\u0442 | **\u0434\u0430** |\n| `E_UNSUPPORTED` | **\u0433\u0440\u0430\u0444 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e**, \u043d\u043e \u0435\u0441\u0442\u044c \u044d\u043b\u0435\u043c\u0435\u043d\u0442/\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0432\u043d\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u044b: \u043c\u0435\u0442\u0430\u043b\u043b\u044b, Se/Te/Sn/As/Pb/I-\u0441\u043e\u043b\u0438, \u0433\u0438\u043f\u0435\u0440\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u044b\u0435 S/P, `*`, \u043f\u043e\u043b\u0438\u043c\u0435\u0440\u043d\u044b\u0435 \u0441\u0441\u044b\u043b\u043a\u0438 | **\u043d\u0435\u0442 \u2014 \u043f\u043e\u043b\u044f \u0441\u0442\u0440\u043e\u0433\u043e `null` + \u043f\u0440\u0438\u0447\u0438\u043d\u0430** | **\u041d\u0415\u0422** |\n| `O_POLICY` | `MULTI_HEAVY`, \u0438\u0437\u043e\u0442\u043e\u043f-\u043c\u0435\u0447\u0435\u043d\u044b\u0435, \u0441\u043e\u043b\u044c\u0432\u0430\u0442-\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 | \u0434\u0430, \u043d\u0430 largest fragment | \u041d\u0415\u0422 |\n\n\u0413\u0440\u0430\u043d\u0438\u0446\u0430 `E_VALENCE` / `E_UNSUPPORTED` \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u0430\u043a: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 grammar \u2192 topology \u2192 element/parameter-table lookup \u2192 sanitize. Lookup **\u0434\u043e** \u0441\u0430\u043d\u0438\u0442\u0430\u0439\u0437\u0430, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043c\u0435\u0442\u0430\u043b\u043b \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u00ab\u0443\u043f\u0430\u0441\u0442\u044c\u00bb \u043a\u0430\u043a \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430. \u0424\u043e\u0440\u043c\u0443\u043b\u044b \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043e\u0447\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430):\n- `parse_failure_rate = (E_GRAMMAR + E_VALENCE + E_INPUT) / (all rows)`\n- `descriptor_coverage = OK / (OK + E_UNSUPPORTED + O_POLICY)` \u2014 \u00ab\u0438\u0437 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438 \u0432 \u0441\u043a\u043e\u0443\u043f\u0435\u00bb\n- `unsupported_share = E_UNSUPPORTED / (all rows)` \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u043e\u0439, \u043a\u0430\u043a \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u0435 \u0441\u043a\u043e\u0443\u043f\u0430, **\u043d\u0435** \u043a\u0430\u043a \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0434\u0430\u043d\u043d\u044b\u0445.\n\n---\n\n## 3. Descriptors: \u043c\u0435\u0442\u043e\u0434, \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a, \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c, \u0440\u0430\u0437\u0440\u044f\u0434\n\nTier A = \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e \u043f\u043e \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u043c\u0443 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e (\u043e\u0448\u0438\u0431\u043a\u0430 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0430\u0433 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u043b\u043e\u0432\u0438\u0442\u0441\u044f \u044e\u043d\u0438\u0442-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f\u043c\u0438). Tier B = \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b, \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430, \u0432 \u0436\u0451\u0441\u0442\u043a\u0438\u0445 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0430\u0445 \u0431\u0435\u0437 sensitivity-\u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442.\n\n| \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u043e | \u041c\u0435\u0442\u043e\u0434 | \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f | Tier | \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c vs RDKit |\n|---|---|---|---|---|\n| MW | \u03a3 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441 (\u0441\u0440\u0435\u0434\u043d\u0438\u0435, IUPAC) | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441 | A | \u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 (<0.01%); \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 monoisotopic-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0435 |\n| numHeavyAtoms, nH, \u0444\u043e\u0440\u043c\u0443\u043b\u0430 | \u043e\u0431\u0445\u043e\u0434 \u0433\u0440\u0430\u0444\u0430 | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A | \u0442\u043e\u0447\u043d\u043e\u0435 |\n| formal charge | \u03a3 \u0437\u0430\u0440\u044f\u0434\u043e\u0432 (\u0432 \u0442.\u0447. \u0438\u0437 bracket-\u043d\u043e\u0442\u0430\u0446\u0438\u0438) | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A | \u0442\u043e\u0447\u043d\u043e\u0435 |\n| HBD / HBA | \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 Lipinski (\u0434\u043e\u043d\u043e\u0440: O/N \u0441 H; \u0430\u043a\u0446\u0435\u043f\u0442\u043e\u0440: N/O \u0441 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f\u043c\u0438 \u0430\u043c\u0438\u0434-O, \u043f\u0438rid\u0438\u043b-N \u0438 \u0442.\u043f.) | \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 Lipinski + RDKit-\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043a\u0430\u043a \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f | A (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435) | \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435; \u00b11 \u043d\u0430 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u0430\u0445/\u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0445 N |\n| ring counts (\u043e\u0431\u0449\u0438\u0435/aromatic), \u0440\u0430\u0437\u043c\u0435\u0440\u043d\u043e\u0441\u0442\u044c | cycle basis + SSSR-\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430 | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A (\u0447\u0438\u0441\u043b\u043e \u043a\u043e\u043b\u0435\u0446) / A\u2212 (SSSR-\u0440\u0430\u0437\u043b\u043e\u0436\u0435\u043d\u0438\u0435) | `\u03bc = E\u2212V+C` \u0442\u043e\u0447\u043d\u043e; \u043f\u043e\u0448\u0442\u0443\u0447\u043d\u044b\u0439 SSSR-\u0441\u043f\u0438\u0441\u043e\u043a \u043c\u043e\u0436\u0435\u0442 differ \u043f\u0440\u0438 tie-break |\n| rotatable bonds | \u0441\u0442\u0440\u043e\u0433\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0432\u043d\u0435 \u043a\u043e\u043b\u044c\u0446\u0430, \u043e\u0431\u0430 \u043a\u043e\u043d\u0446\u0430 \u043d\u0435 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u044b, \u043d\u0435 \u0430\u043c\u0438\u0434 C\u2013N, \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u0430\u044f | RDKit-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439 | A (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435), \u043d\u043e **\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435-\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e** | \u00b11; **\u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u043d\u0435\u0441\u0442\u0438 \u043c\u0435\u0442\u043a\u0443 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f**, \u00ab\u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u043e\u0433\u043e\u00bb \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f RB \u043d\u0435\u0442 |\n| TPSA | \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u0445 \u0432\u043a\u043b\u0430\u0434\u043e\u0432 Ertl/Topliss (~60 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432) \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 subgraph-\u043c\u0430\u0442\u0447\u0435\u0440 | **\u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430** | A\u2212 (\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435) | \u00b11\u20132 \u00c5\u00b2 \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435; \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u0437-\u0437\u0430 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u043e\u0433\u043e \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u0430 |\n| logP | \u0430\u0442\u043e\u043c-\u0442\u0438\u043f\u043e\u0432\u044b\u0435 \u0432\u043a\u043b\u0430\u0434\u044b (XLogP/Wildman\u2013Crippen-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u0443\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440) | \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 + **\u043d\u0430\u0448 \u0443\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0442\u0438\u043f\u043e\u0432** | **B** | MAE \u22480.4\u20130.7 logU \u0434\u043b\u044f drug-like; \u0445\u0432\u043e\u0441\u0442\u044b (\u0433\u0430\u043b\u043e-, \u043f\u043e\u043b\u0438\u0446\u0438\u043a\u043b\u044b, \u0441\u0443\u043b\u044c\u0444\u043e\u043d\u044b) \u2014 \u0434\u043e 2\u20133; \u0442\u043e\u0447\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0437\u0434\u0435\u0441\u044c **\u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u044b** |\n| acid_sites / base_sites (LOW-CONFIDENCE) | \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0443\u0436\u0435 \u043d\u0443\u0436\u043d\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430 \u0444\u0443\u043d\u043a\u0446. \u0433\u0440\u0443\u043f\u043f (\u043a\u0438\u0441\u043b\u044b\u0435: COOH, \u0441\u0443\u043b\u044c\u0444\u043e\u043d\u0430\u0442/\u0441\u0443\u043b\u044c\u0444\u043e\u043d\u0430\u043c\u0438\u0434, \u0442\u0435\u0442\u0440\u0430\u0437\u043e\u043b, \u0444\u043e\u0441\u0444\u0430\u0442, \u0444\u0435\u043d\u043e\u043b; \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435: \u0430\u043b\u0438\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043c\u0438\u043d, \u0430\u043c\u0438\u0434\u0438\u043d, \u0433\u0443\u0430\u043d\u0438\u0434\u0438\u043d, \u043f\u0438\u0440\u0438\u0434\u0438\u043b) | **\u043d\u0430\u0448\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 (\u0441\u0442\u0438\u043f\u0443\u043b\u044f\u0442\u0438\u0432\u043d\u043e\u0435)** | B\u2212 | \u0432\u043d\u0435\u0448\u043d\u0435\u043c\u0443 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u043d\u0435 \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442 \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e; \u044d\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0437 \u0438\u0437 \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432 \u0438 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u043e\u0432 |\n| pKa | **\u0412\u042b\u0427\u0401\u0420\u041a\u041d\u0423\u0422 \u041f\u041e\u041b\u041d\u041e\u0421\u0422\u042c\u042e** | \u2014 | \u2014 | scope decision, \u00a78 |\n\n**\u041b\u043e\u0433\u0438\u043a\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f TPSA/logP (\u043f\u043e \u0432\u0430\u0448\u0435\u043c\u0443 \u0443\u043a\u0430\u0437\u0430\u043d\u0438\u044e).** TPSA \u2014 \u00ab\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u00bb: \u043e\u0436\u0438\u0434\u0430\u0435\u043c \u043f\u043e\u0447\u0442\u0438 \u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435, \u0438 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0441 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043e\u043c \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u043c \u043a\u0430\u043a \u0431\u0430\u0433 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438. logP \u2014 \u00ab\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430 \u0441 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0451\u043d\u043d\u044b\u043c \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u043c\u00bb: \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u043c \u043a\u0430\u043a \u043d\u043e\u0440\u043c\u0443, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 logP \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 verdict'\u0430\u0445, \u0430 \u0432\u0445\u043e\u0434\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0435\u0440\u0435\u0437 \u00a75 (sensitivity band), \u0438 \u043d\u0438 \u0432 \u043e\u0434\u0438\u043d PASS/FAIL-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441 \u0436\u0451\u0441\u0442\u043a\u0438\u043c \u0434\u043e\u043f\u0443\u0441\u043a\u043e\u043c.\n\n---\n\n## 4. Controls\n\n**4.1 \u0421\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u043f\u0430\u043d\u0435\u043b\u044c (positive controls).** \u041f\u0430\u043d\u0435\u043b\u044c \u0437\u0430\u043c\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u0441 \u043a\u043e\u043b\u043e\u043d\u043a\u043e\u0439 `source`; \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0446\u0438\u0442\u0438\u0440\u0443\u0435\u043c\u043e\u0433\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 PASS/FAIL, \u0430 \u0441\u043b\u0443\u0436\u0438\u0442 regression-pin'\u043e\u043c. MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f, \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 (\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430 \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435; \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043d\u0430 \u043f\u0440\u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430). \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 \u2014 \u0442\u0440\u0430\u043d\u0441\u043a\u0440\u0438\u043f\u0446\u0438\u044f \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b/PubChem-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u0438 **\u0442\