\u043e\u0441\u0442\u044c\u044e; acid_sites/base_sites \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0443\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u043e\u0433\u043e \u0444\u0443\u043d\u043a\u0446.-\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430, \u0438\u043d\u0430\u0447\u0435 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f", "\u0421\u0440\u0435\u0434\u043d\u0438\u0435 (\u043d\u0435 \u043c\u043e\u043d\u043e\u0438\u0437\u043e\u0442\u043e\u043f\u043d\u044b\u0435) \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043c\u0430\u0441\u0441\u044b; \u0443\u0440\u043e\u0432\u0435\u043d\u044c 2D: \u0431\u0435\u0437 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043d\u043e\u0439/\u043f\u0440\u043e\u0442\u043e\u043d\u043d\u043e\u0439/\u0441\u043e\u043b\u044c\u0432\u0430\u0442\u043d\u043e\u0439 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u0441\u0442\u0435\u0440\u0435\u043e\u0445\u0438\u043c\u0438\u044f \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f", "RB \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442\u0441\u044f \u0441 \u044f\u0432\u043d\u043e\u0439 \u043c\u0435\u0442\u043a\u043e\u0439 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f (strict, amide-excluded); \u00ab\u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u043e\u0433\u043e\u00bb \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f RB \u043d\u0435\u0442", "\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f TPSA/HBD/HBA/RB \u0432 \u043f\u0430\u043d\u0435\u043b\u0438 \u0438 \u0432\u0441\u0435 \u0446\u0438\u0444\u0440\u044b \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438 \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0435 (\u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0430/PubChem-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e), \u0432 \u0434\u0430\u043d\u043d\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f; \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430 \u0442\u043e\u043b\u044c\u043a\u043e MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430", "\u041a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 5\u201320 \u043c\u0441/\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 \u043d\u0430 \u044f\u0434\u0440\u043e \u2014 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u043b\u044f \u0447\u0438\u0441\u0442\u043e\u0433\u043e Python \u0441 pattern-\u043c\u0430\u0442\u0447\u0438\u043d\u0433\u043e\u043c, \u0430 \u043d\u0435 \u0437\u0430\u043c\u0435\u0440", "\u0410\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0439 (spec/\u043f\u0430\u043d\u0435\u043b\u0438/\u043f\u043e\u0440\u043e\u0433\u0438) \u0445\u044d\u0448\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0438 \u0437\u0430\u043c\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430; \u044d\u0442\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438"], "uncertainties": ["\u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u043e\u043b\u0438 E_GRAMMAR / E_UNSUPPORTED \u0434\u043b\u044f \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 (\u043e\u0441\u043