14 \u043d\u0435 \u00ab\u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043d\u0430\u044f \u0437\u0430\u0434\u0430\u0447\u0430 \u043f\u0440\u043e \u043f\u0430\u0440\u0441\u0435\u0440\u00bb, \u0430 \u0434\u0432\u0435 \u0440\u0443\u043a\u0438-\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043f\u043e\u0432\u0435\u0440\u0445\u043d\u043e\u0441\u0442\u0438:\n1. **\u0421\u0432\u043e\u0439 SMILES/SDF-\u043f\u0430\u0440\u0441\u0435\u0440.** \u041e\u0448\u0438\u0431\u043a\u0430 \u0433\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u043a\u0438 \u0438\u043b\u0438 \u043f\u0435\u0440\u0446\u0435\u043f\u0446\u0438\u0438 (\u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c, implicit H, \u0437\u0430\u0440\u044f\u0434\u044b) \u0434\u0430\u0451\u0442 *\u043c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u043e \u043d\u0435\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0435* \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b, \u0430 \u043d\u0435 exception. \u042d\u0442\u043e \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043e\u0448\u0438\u0431\u043a\u0438, \u0438 \u043e\u043d \u043d\u0435 \u043b\u043e\u0432\u0438\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u043c\u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u043d\u044b\u043c\u0438 \u0442\u0435\u0441\u0442\u0430\u043c\u0438.\n2. **\u0412\u0440\u0443\u0447\u043d\u0443\u044e \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u044b\u0435 \u0442\u0430\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u0432\u043a\u043b\u0430\u0434\u044b** (TPSA-\u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b Ertl/Topliss, \u0442\u0438\u043f\u044b \u0430\u0442\u043e\u043c\u043e\u0432 \u0434\u043b\u044f logP). \u041e\u043f\u0435\u0447\u0430\u0442\u043a\u0430/\u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u044b\u0439 \u043f\u0430\u0442\u0442\u0435\u0440\u043d \u2192 \u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0432\u0441\u044f\u043a\u043e\u0433\u043e \u0441\u0438\u0433\u043d\u0430\u043b\u0430 \u043e\u0431 \u043e\u0448\u0438\u0431\u043a\u0435.\n\n\u0421\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435, \u0437\u0430\u0434\u0430\u044e\u0449\u0435\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0432\u0441\u0435\u0433\u043e \u0434\u0438\u0437\u0430\u0439\u043d\u0430: **\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u0434\u0435\u043b\u044f\u0442\u0441\u044f \u043d\u0430 \u0434\u0432\u0430 \u0441\u043e\u0440\u0442\u0430**, \u0438 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u0438\u0445 \u0432 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0430\u0445 \u043d\u0435\u043b\u044c\u0437\u044f (\u00a73 Tier A / Tier B). \u0412\u043d\u0435\u0448\u043d\u0435\u0439 \u0442\u043e\u0447\u043a\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435\u0442 (\u00a77).\n\n---\n\n## 2. Input / ingestion\n\n**\u0424\u043e\u0440\u043c\u0430\u0442-\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u0432\u0445\u043e\u0434** (\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 \u0437\u0430\u043f\u0443\u0441\u043a\u0430): CSV/TSV \u0441\u043e SMILES-\u043a\u043e\u043b\u043e\u043d\u043a\u043e\u0439, `.smi`, SDF. \u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u2014 \u0444\u043e\u0440\u043c\u0430\u0442 \u043d\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f, \u0430 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f.\n\n**Format diagnostics (\u0434\u043e \u043b\u044e\u0431\u043e\u0439 \u0445\u0438\u043c\u0438\u0438, \u0434\u0435\u0448\u0451\u0432\u044b\u0439 pass):** magic-bytes \u2192 gzip/zstd/plain; encoding probe (utf-8 strict \u2192 latin-1 fallback, \u0444\u0430\u043a\u0442 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f); delimiter sniff \u043f\u043e \u043f\u0435\u0440\u0432\u044b\u043c N \u0441\u0442\u0440\u043e\u043a\u0430\u043c; header detection; \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0441\u0442\u0440\u043e\u043a \u0438 \u043f\u043e\u043b\u0435\u0439; \u0434\u0435\u0442\u0435\u043a\u0442 \u00ab\u043e\u0434\u043d\u0430 \u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u0431\u0435\u0437 \u0437\u0430\u043f\u044f\u0442\u044b\u0445\u00bb \u2192 smi-\u0440\u0435\u0436\u0438\u043c. \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 machine-readable `ingest_manifest.json` (\u0444\u043e\u0440\u043c\u0430\u0442, encoding, \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044c, \u0438\u043c\u044f SMILES-\u043a\u043e\u043b\u043e\u043d\u043a\u0438, \u0447\u0438\u0441\u043b\u043e \u0441\u0442\u0440\u043e\u043a). \u041e\u043d \u0436\u0435 \u2014 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438.\n\n**\u0415\u0434\u0438\u043d\u044b\u0439 molgraph-\u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441.** SMILES-\u043f\u0430\u0440\u0441\u0435\u0440 \u0438 SDF-\u043f\u0430\u0440\u0441\u0435\u0440 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442 \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0442\u0438\u043f: `Atom{idx, el, charge, h_count, is_aromatic, isotope, in_ring_sizes[]}`, `Bond{i, j, order, aromatic}`, `fragments[]`, `parse_provenance`. \u0412\u0441\u0435 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u2014 \u0447\u0438\u0441\u0442\u044b\u0435 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u043e\u0442 molgraph \u0438 **\u043d\u0435 \u0437\u043d\u0430\u044e\u0442 \u043e \u0432\u0445\u043e\u0434\u043d\u043e\u043c \u0444\u043e\u0440\u043c\u0430\u0442\u0435**. \u042d\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c SDF\u2194SMILES (\u00a74.3) \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0442 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0434\u0432\u0443\u0445 \u043f\u0443\u0442\u0435\u0439.\n- SMILES: \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440 + \u0440\u0435\u043a\u0443\u0440\u0441\u0438\u0432\u043d\u044b\u0439 \u0441\u043f\u0443\u0441\u043a; \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c: \u043e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e-\u0430\u043b\u0444\u0430\u0432\u0438\u0442, `[...]` (\u0438\u0437\u043e\u0442\u043e\u043f, \u0437\u0430\u0440\u044f\u0434, H-\u0441\u0447\u0451\u0442), \u0441\u0432\u044f\u0437\u0438 `- = # : / \\ .`, \u0432\u0435\u0442\u043a\u0438, \u043a\u043e\u043b\u044c\u0446\u0430 `%nn`, `*` (\u043a\u0430\u043a wildcard \u2192 OUT_OF_POLICY). \u0421\u0442\u0435\u0440\u0435\u043e (`@`, `@@`, `/`, `\\`) \u043f\u0430\u0440\u0441\u0438\u0442\u0441\u044f \u0438 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0441 \u0437\u0430\u043f\u0438\u0441\u044c\u044e \u0432 \u043b\u043e\u0433 (2D-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u043e\u0442 \u043d\u0435\u0433\u043e \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u044f\u0442).\n- SDF: V2000 counts-line \u2192 atom block \u2192 bond block \u2192 `M  END`; \u043f\u0440\u043e\u043a\u0438\u0434\u043a\u0430 property-fields \u0432 \u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u0435. V3000 \u2014 \u044f\u0432\u043d\u044b\u0439 \u043e\u0442\u043a\u0430\u0437 \u0441 \u043a\u043e\u0434\u043e\u043c ledger, \u0430 \u043d\u0435 \u0442\u0438\u0445\u0430\u044f \u043f\u043e\u0440\u0447\u0430.\n\n**\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u043e \u043c\u0443\u043b\u044c\u0442\u0438\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u043d\u044b\u043c \u0437\u0430\u043f\u0438\u0441\u044f\u043c.** \u041f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e `largest_fragment` \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432; \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e \u043f\u0438\u0448\u0443\u0442\u0441\u044f `n_fragments`, `n_heavy_fragments`, `n_atoms_dropped`, `salt_formula`. \u041f\u0440\u0430\u0432\u0438\u043b\u043e \u043e\u0434\u043d\u043e\u0437\u043d\u0430\u0447\u043d\u043e: ties \u2192 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442 \u0441 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u043c \u0438\u043d\u0434\u0435\u043a\u0441\u043e\u043c \u0430\u0442\u043e\u043c\u0430, \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d. \u0417\u0430\u043f\u0438\u0441\u0438 \u0441 >1 \u0442\u044f\u0436\u0451\u043b\u044b\u043c \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043e\u043c \u043f\u043e\u043c\u0435\u0447\u0430\u044e\u0442\u0441\u044f `MULTI_HEAVY` \u0438 **\u043d\u0435 \u0432\u0445\u043e\u0434\u044f\u0442** \u0432 headline-\u043c\u0435\u0442\u0440\u0438\u043a\u0438 (\u043d\u043e \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u00ab\u043f\u043b\u043e\u0445\u0438\u043c\u0438\u00bb \u2014 \u044d\u0442\u043e \u0438\u043d\u043e\u0439 \u0440\u0435\u0436\u0438\u043c).\n\n**Failure ledger \u2014 \u0442\u0430\u043a\u0441\u043e\u043d\u043e\u043c\u0438\u044f \u0441 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0432\u044b\u0445\u043e\u0434\u0430\u043c\u0438.** \u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435: \u00ab\u043d\u0435 \u043f\u0430\u0440\u0441\u0438\u0442\u0441\u044f\u00bb \u0438 \u00ab\u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0438\u043b\u0430\u0441\u044c, \u043d\u043e \u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u0432\u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438\u00bb \u2014 **\u0434\u0432\u0430 \u0440\u0430\u0437\u043d\u044b\u0445 \u0432\u044b\u0445\u043e\u0434\u0430**, \u0438 \u0441\u0432\u043e\u0434\u0438\u0442\u044c \u0438\u0445 \u0432 \u043e\u0434\u043d\u0443 \u0434\u043e\u043b\u044e \u043d\u0435\u0443\u0434\u0430\u0447 \u043d\u0435\u043b\u044c\u0437\u044f (\u0438\u043d\u0430\u0447\u0435 headline-\u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u0432\u0440\u0451\u0442 \u0432 \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b: \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0438 \u0441 \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c\u0438 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u00ab\u0441\u043b\u043e\u043c\u0430\u043d\u043d\u044b\u043c\u0438\u00bb, \u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0431\u0438\u0442\u044b\u0435 SMILES \u0442\u043e\u043d\u0443\u0442 \u0432 \u0448\u0443\u043c\u0435).\n\n| \u041a\u043e\u0434 | \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 | \u0422\u044f\u043d\u0435\u0442 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b? | \u0412\u0445\u043e\u0434\u0438\u0442 \u0432 parse-failure denominator? |\n|---|---|---|---|\n| `OK` | \u043f\u043e\u043b\u043d\u044b\u0439 \u0433\u0440\u0430\u0444, \u0432\u0441\u0451 \u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u0445 | \u0434\u0430 | \u2014 |\n| `E_INPUT` | \u043f\u0443\u0441\u0442\u043e\u0435 \u043f\u043e\u043b\u0435 / \u043d\u0435\u0442 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 / \u043d decodable | \u043d\u0435\u0442 | \u0434\u0430 (data hygiene) |\n| `E_GRAMMAR` | \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u0430\u044f \u0432\u0435\u0442\u043a\u0430, \u043d\u0435\u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0435/\u043d\u0435\u0437\u0430\u043c\u043a\u043d\u0443\u0442\u043e\u0435 \u043a\u043e\u043b\u044c\u0446\u043e, \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u0441\u0438\u043c\u0432\u043e\u043b, `M  END` \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, V3000 | \u043d\u0435\u0442 | **\u0434\u0430 (headline parse-failure)** |\n| `E_VALENCE` | \u0433\u0440\u0430\u0444 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d, \u043d\u043e \u0441\u0430\u043d\u0438\u0442\u0430\u0439\u0437 \u043d\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 (\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c/\u0430\u0440\u043e\u043c\u0430\u0442\u0438\u043a\u0430) | \u043d\u0435\u0442 | **\u0434\u0430** |\n| `E_UNSUPPORTED` | **\u0433\u0440\u0430\u0444 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e**, \u043d\u043e \u0435\u0441\u0442\u044c \u044d\u043b\u0435\u043c\u0435\u043d\u0442/\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0432\u043d\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u044b: \u043c\u0435\u0442\u0430\u043b\u043b\u044b, Se/Te/Sn/As/Pb/I-\u0441\u043e\u043b\u0438, \u0433\u0438\u043f\u0435\u0440\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u044b\u0435 S/P, `*`, \u043f\u043e\u043b\u0438\u043c\u0435\u0440\u043d\u044b\u0435 \u0441\u0441\u044b\u043b\u043a\u0438 | **\u043d\u0435\u0442 \u2014 \u043f\u043e\u043b\u044f \u0441\u0442\u0440\u043e\u0433\u043e `null` + \u043f\u0440\u0438\u0447\u0438\u043d\u0430** | **\u041d\u0415\u0422** |\n| `O_POLICY` | `MULTI_HEAVY`, \u0438\u0437\u043e\u0442\u043e\u043f-\u043c\u0435\u0447\u0435\u043d\u044b\u0435, \u0441\u043e\u043b\u044c\u0432\u0430\u0442-\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 | \u0434\u0430, \u043d\u0430 largest fragment | \u041d\u0415\u0422 |\n\n\u0413\u0440\u0430\u043d\u0438\u0446\u0430 `E_VALENCE` / `E_UNSUPPORTED` \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u0430\u043a: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 grammar \u2192 topology \u2192 element/parameter-table lookup \u2192 sanitize. Lookup **\u0434\u043e** \u0441\u0430\u043d\u0438\u0442\u0430\u0439\u0437\u0430, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043c\u0435\u0442\u0430\u043b\u043b \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u00ab\u0443\u043f\u0430\u0441\u0442\u044c\u00bb \u043a\u0430\u043a \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430. \u0424\u043e\u0440\u043c\u0443\u043b\u044b \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043e\u0447\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430):\n- `parse_failure_rate = (E_GRAMMAR + E_VALENCE + E_INPUT) / (all rows)`\n- `descriptor_coverage = OK / (OK + E_UNSUPPORTED + O_POLICY)` \u2014 \u00ab\u0438\u0437 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438 \u0432 \u0441\u043a\u043e\u0443\u043f\u0435\u00bb\n- `unsupported_share = E_UNSUPPORTED / (all rows)` \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u043e\u0439, \u043a\u0430\u043a \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u0435 \u0441\u043a\u043e\u0443\u043f\u0430, **\u043d\u0435** \u043a\u0430\u043a \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0434\u0430\u043d\u043d\u044b\u0445.\n\n---\n\n## 3. Descriptors: \u043c\u0435\u0442\u043e\u0434, \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a, \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c, \u0440\u0430\u0437\u0440\u044f\u0434\n\nTier A = \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e \u043f\u043e \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u043c\u0443 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e (\u043e\u0448\u0438\u0431\u043a\u0430 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0430\u0433 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u043b\u043e\u0432\u0438\u0442\u0441\u044f \u044e\u043d\u0438\u0442-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f\u043c\u0438). Tier B = \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b, \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430, \u0432 \u0436\u0451\u0441\u0442\u043a\u0438\u0445 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0430\u0445 \u0431\u0435\u0437 sensitivity-\u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442.\n\n| \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u043e | \u041c\u0435\u0442\u043e\u0434 | \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f | Tier | \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c vs RDKit |\n|---|---|---|---|---|\n| MW | \u03a3 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441 (\u0441\u0440\u0435\u0434\u043d\u0438\u0435, IUPAC) | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441 | A | \u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 (<0.01%); \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 monoisotopic-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0435 |\n| numHeavyAtoms, nH, \u0444\u043e\u0440\u043c\u0443\u043b\u0430 | \u043e\u0431\u0445\u043e\u0434 \u0433\u0440\u0430\u0444\u0430 | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A | \u0442\u043e\u0447\u043d\u043e\u0435 |\n| formal charge | \u03a3 \u0437\u0430\u0440\u044f\u0434\u043e\u0432 (\u0432 \u0442.\u0447. \u0438\u0437 bracket-\u043d\u043e\u0442\u0430\u0446\u0438\u0438) | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A | \u0442\u043e\u0447\u043d\u043e\u0435 |\n| HBD / HBA | \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 Lipinski (\u0434\u043e\u043d\u043e\u0440: O/N \u0441 H; \u0430\u043a\u0446\u0435\u043f\u0442\u043e\u0440: N/O \u0441 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f\u043c\u0438 \u0430\u043c\u0438\u0434-O, \u043f\u0438rid\u0438\u043b-N \u0438 \u0442.\u043f.) | \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 Lipinski + RDKit-\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043a\u0430\u043a \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f | A (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435) | \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435; \u00b11 \u043d\u0430 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u0430\u0445/\u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0445 N |\n| ring counts (\u043e\u0431\u0449\u0438\u0435/aromatic), \u0440\u0430\u0437\u043c\u0435\u0440\u043d\u043e\u0441\u0442\u044c | cycle basis + SSSR-\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430 | \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 | A (\u0447\u0438\u0441\u043b\u043e \u043a\u043e\u043b\u0435\u0446) / A\u2212 (SSSR-\u0440\u0430\u0437\u043b\u043e\u0436\u0435\u043d\u0438\u0435) | `\u03bc = E\u2212V+C` \u0442\u043e\u0447\u043d\u043e; \u043f\u043e\u0448\u0442\u0443\u0447\u043d\u044b\u0439 SSSR-\u0441\u043f\u0438\u0441\u043e\u043a \u043c\u043e\u0436\u0435\u0442 differ \u043f\u0440\u0438 tie-break |\n| rotatable bonds | \u0441\u0442\u0440\u043e\u0433\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0432\u043d\u0435 \u043a\u043e\u043b\u044c\u0446\u0430, \u043e\u0431\u0430 \u043a\u043e\u043d\u0446\u0430 \u043d\u0435 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u044b, \u043d\u0435 \u0430\u043c\u0438\u0434 C\u2013N, \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u0430\u044f | RDKit-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439 | A (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435), \u043d\u043e **\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435-\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e** | \u00b11; **\u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u043d\u0435\u0441\u0442\u0438 \u043c\u0435\u0442\u043a\u0443 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f**, \u00ab\u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u043e\u0433\u043e\u00bb \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f RB \u043d\u0435\u0442 |\n| TPSA | \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u0445 \u0432\u043a\u043b\u0430\u0434\u043e\u0432 Ertl/Topliss (~60 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432) \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 subgraph-\u043c\u0430\u0442\u0447\u0435\u0440 | **\u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430** | A\u2212 (\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435) | \u00b11\u20132 \u00c5\u00b2 \u043f\u0440\u0438 \u043f\u043e\u043b\u043d\u043e\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0435; \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u0437-\u0437\u0430 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u043e\u0433\u043e \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u0430 |\n| logP | \u0430\u0442\u043e\u043c-\u0442\u0438\u043f\u043e\u0432\u044b\u0435 \u0432\u043a\u043b\u0430\u0434\u044b (XLogP/Wildman\u2013Crippen-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u0443\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440) | \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 + **\u043d\u0430\u0448 \u0443\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0442\u0438\u043f\u043e\u0432** | **B** | MAE \u22480.4\u20130.7 logU \u0434\u043b\u044f drug-like; \u0445\u0432\u043e\u0441\u0442\u044b (\u0433\u0430\u043b\u043e-, \u043f\u043e\u043b\u0438\u0446\u0438\u043a\u043b\u044b, \u0441\u0443\u043b\u044c\u0444\u043e\u043d\u044b) \u2014 \u0434\u043e 2\u20133; \u0442\u043e\u0447\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0437\u0434\u0435\u0441\u044c **\u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u044b** |\n| acid_sites / base_sites (LOW-CONFIDENCE) | \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0443\u0436\u0435 \u043d\u0443\u0436\u043d\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430 \u0444\u0443\u043d\u043a\u0446. \u0433\u0440\u0443\u043f\u043f (\u043a\u0438\u0441\u043b\u044b\u0435: COOH, \u0441\u0443\u043b\u044c\u0444\u043e\u043d\u0430\u0442/\u0441\u0443\u043b\u044c\u0444\u043e\u043d\u0430\u043c\u0438\u0434, \u0442\u0435\u0442\u0440\u0430\u0437\u043e\u043b, \u0444\u043e\u0441\u0444\u0430\u0442, \u0444\u0435\u043d\u043e\u043b; \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435: \u0430\u043b\u0438\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043c\u0438\u043d, \u0430\u043c\u0438\u0434\u0438\u043d, \u0433\u0443\u0430\u043d\u0438\u0434\u0438\u043d, \u043f\u0438\u0440\u0438\u0434\u0438\u043b) | **\u043d\u0430\u0448\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 (\u0441\u0442\u0438\u043f\u0443\u043b\u044f\u0442\u0438\u0432\u043d\u043e\u0435)** | B\u2212 | \u0432\u043d\u0435\u0448\u043d\u0435\u043c\u0443 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u043d\u0435 \u043f\u043e\u0434\u043b\u0435\u0436\u0438\u0442 \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e; \u044d\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0437 \u0438\u0437 \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432 \u0438 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u043e\u0432 |\n| pKa | **\u0412\u042b\u0427\u0401\u0420\u041a\u041d\u0423\u0422 \u041f\u041e\u041b\u041d\u041e\u0421\u0422\u042c\u042e** | \u2014 | \u2014 | scope decision, \u00a78 |\n\n**\u041b\u043e\u0433\u0438\u043a\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f TPSA/logP (\u043f\u043e \u0432\u0430\u0448\u0435\u043c\u0443 \u0443\u043a\u0430\u0437\u0430\u043d\u0438\u044e).** TPSA \u2014 \u00ab\u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430\u00bb: \u043e\u0436\u0438\u0434\u0430\u0435\u043c \u043f\u043e\u0447\u0442\u0438 \u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435, \u0438 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0441 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043e\u043c \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u043c \u043a\u0430\u043a \u0431\u0430\u0433 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438. logP \u2014 \u00ab\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430 \u0441 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0451\u043d\u043d\u044b\u043c \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u043c\u00bb: \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u043c \u043a\u0430\u043a \u043d\u043e\u0440\u043c\u0443, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 logP \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 verdict'\u0430\u0445, \u0430 \u0432\u0445\u043e\u0434\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0435\u0440\u0435\u0437 \u00a75 (sensitivity band), \u0438 \u043d\u0438 \u0432 \u043e\u0434\u0438\u043d PASS/FAIL-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441 \u0436\u0451\u0441\u0442\u043a\u0438\u043c \u0434\u043e\u043f\u0443\u0441\u043a\u043e\u043c.\n\n---\n\n## 4. Controls\n\n**4.1 \u0421\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u043f\u0430\u043d\u0435\u043b\u044c (positive controls).** \u041f\u0430\u043d\u0435\u043b\u044c \u0437\u0430\u043c\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u0441 \u043a\u043e\u043b\u043e\u043d\u043a\u043e\u0439 `source`; \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u0446\u0438\u0442\u0438\u0440\u0443\u0435\u043c\u043e\u0433\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 PASS/FAIL, \u0430 \u0441\u043b\u0443\u0436\u0438\u0442 regression-pin'\u043e\u043c. MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f, \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 (\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430 \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435; \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043d\u0430 \u043f\u0440\u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430). \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043a\u043e\u043b\u043e\u043d\u043a\u0438 \u2014 \u0442\u0440\u0430\u043d\u0441\u043a\u0440\u0438\u043f\u0446\u0438\u044f \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b/PubChem-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u0438 **\u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 \u0446\u0438\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430** (\u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 RDKit/PubChem \u0437\u0434\u0435\u0441\u044c \u043d\u0435\u0442 \u2014 \u00a77).\n\n| \u0412\u0435\u0449\u0435\u0441\u0442\u0432\u043e | SMILES | \u0424\u043e\u0440\u043c\u0443\u043b\u0430 | MW (\u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043d\u043e) | HBD | HBA | RB* | TPSA (ref) |\n|---|---|---|---|---|---|---|---|\n| ethanol | `CCO` | C2H6O | 46.069 | 1 | 1 | 0 | 20.23 |\n| benzene | `c1ccccc1` | C6H6 | 78.114 | 0 | 0 | 0 | 0.00 |\n| pyridine | `c1ccncc1` | C5H5N | 79.102 | 0 | 1 | 0 | 12.89 |\n| urea | `NC(=O)N` | CH4N2O | 60.056 | 1 | 1 | 0 | 43.09 |\n| aspirin | `CC(=O)Oc1ccccc1C(=O)O` | C9H8O4 | 180.159 | 1 | 4 | 3 | 63.60 |\n| caffeine | `Cn1cnc2c1c(=O)n(c(=O)n2C)C` | C8H10N4O2 | 194.194 | 0 | 3 | 0 | 58.44 |\n| glucose | `OC[C@H]1OC(O)[C@H](O)[C@@H](O)[C@@H]1O` | C6H12O6 | 180.156 | 5 | 6 | 0 | 110.59 |\n| ibuprofen | `CC(C)Cc1ccc(cc1)C(C)C(=O)O` | C13H18O2 | 206.285 | 1 | 2 | 4 | 37.30 |\n| nicotine | `CN1CCCC1c2cncc2` | C10H14N2 | 162.236 | 0 | 2 | 1 | 17.82 |\n| nitrobenzene | `O=[N+]([O-])c1ccccc1` | C6H5NO2 | 123.111 | 0 | 3 | 0 | 126.19 |\n| metformin | `CN=C(N)N=C(C)N` | C4H11N5 | 129.167 | 1 | 3 | 5 | 90.15 |\n| taurine | `NCCS(=O)(=O)O` | C2H7NO3S | 125.142 | 2 | 4 | 2 | 88.85 |\n| ATP | `Nc1ncnc2n(cnc12)[C@@H]1O[C@H](COP(=O)(O)OP(=O)(O)OP(=O)(O)O)[C@@H](O)[C@H]1O` | C10H16N5O13P3 | 507.182 | 4 | 16 | 14 | 263.48 |\n\n\\* RB \u2014 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0441\u0438\u043b\u044c\u043d\u043e \u043e\u0442 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f; \u0432 \u043f\u0430\u043d\u0435\u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 (strict, amide-excluded),PubChem-\u0441\u0435\u043c\u0435\u0439\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043b\u0438\u0447\u0430\u0442\u044c\u0441\u044f \u0438 \u044d\u0442\u043e \u043d\u0435 \u0431\u0430\u0433.\n\n\u041f\u0430\u043d\u0435\u043b\u044c \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442: \u0437\u0430\u0440\u044f\u0436\u0435\u043d\u043d\u044b\u0435/\u043d\u0435\u0439\u0442\u0440\u0430\u043b\u0438\u0437\u0443\u044e\u0449\u0438\u0435 \u0433\u0440\u0443\u043f\u043f\u044b (nitrobenzene, taurine), \u043f\u043e\u043b\u0438\u043e\u043b\u044c\u043d\u044b\u0435 \u0441\u0435\u0442\u0438 (glucose), \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043d\u044b\u0445 \u0430\u043c\u0438\u0434\u0438\u043d\u043e\u0432 (metformin), \u043c\u0430\u043a\u0440\u043e-\u043a\u0438\u0441\u043b\u043e\u0440\u043e\u0434\u043d\u0443\u044e/phosphat\u043d\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443 (ATP), \u00ab\u043d\u0443\u043b\u0435\u0432\u044b\u0435\u00bb \u043f\u0440\u0435\u0434\u0435\u043b\u044b (benzene: TPSA=0).\n\n**\u0417\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0441\u043a\u0438 (\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442, \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u043c\u0435\u0441\u0442\u0435 \u0441\u65b0\u7684 \u0445\u044d\u0448\u0435\u043c):** MW \u00b10.05; HBD/HBA \u0442\u043e\u0447\u043d\u043e\u0435; TPSA \u00b12.0 \u00c5\u00b2; RB \u00b10 (\u043f\u0440\u0438 \u0442\u043e\u043c \u0436\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0438) \u0441 \u044f\u0432\u043d\u043e\u0439 \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0435\u0439 \u043a\u0430\u043a *spec-\u0432\u043e\u043f\u0440\u043e\u0441*, \u0430 \u043d\u0435 \u043a\u0430\u043a \u043c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u044b\u0439 \u0434\u043e\u043f\u0443\u0441\u043a; logP **\u0431\u0435\u0437** \u0434\u043e\u043f\u0443\u0441\u043a\u0430 (Tier B, \u043d\u0435 \u0432 PASS/FAIL); sanity-\u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b: MW>0, TPSA\u22650, HBD\u2264HBA+\u2026 \u043d\u0435\u0442 \u2014 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e: `HBD \u2264 N(OH)+N(NH)`, `HBA \u2264 nHeavy`, `RB \u2264 nHeavy\u22121`.\n\n**4.2 Negative controls (\u0432\u044b \u043e\u0431\u044f\u0437\u0430\u043d\u044b \u0443\u043f\u0430\u0441\u0442\u044c, \u0438 \u0438\u043c\u0435\u043d\u043d\u043e \u0432 \u043d\u0443\u0436\u043d\u044b\u0439 \u043a\u043e\u0434).** \u0412\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043b\u043e\u0432\u0438\u0442, \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0441\u0442\u043e\u0438\u0442; \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u0437\u0430\u0432\u0435\u0434\u043e\u043c\u043e \u0431\u0438\u0442\u044b\u0435 \u0432\u0445\u043e\u0434\u044b \u0441 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u043c \u043a\u043e\u0434\u043e\u043c ledger:\n\n| \u0412\u0445\u043e\u0434 | \u041e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u043a\u043e\u0434 |\n|---|---|\n| `` (\u043f\u0443\u0441\u0442\u043e) | `E_INPUT` |\n| `CC(C)(C)(C)C` (5 \u0441\u0432\u044f\u0437\u0435\u0439 \u0443 C) | `E_VALENCE` |\n| `c1ccccc` | `E_GRAMMAR` (ring unclosed) |\n| `CC1CC2CC1` | `E_GRAMMAR` (orphan ring closure) |\n| `C(C(C)C` | `E_GRAMMAR` (unbalanced branch) |\n| `C1=CC=CC=C1` vs `c1ccccc1` | \u043e\u0431\u0430 `OK` \u0438 **\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435** \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b (kekul\u00e9/aromatic \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c) |\n| `[Na+].[Cl-]` | `OK` + `O_POLICY`/`MULTI_HEAVY`, \u043d\u0435 failure |\n| `[Pt](Cl)(Cl)(N)N` | `E_UNSUPPORTED` (\u043d\u0435 `E_VALENCE`!) |\n| `C[Sn](C)(C)C` | `E_UNSUPPORTED` |\n| `C1=CC=C[C@H]1` (\u0430\u0440\u043e\u043c\u0430\u0442\u0438\u043a\u0430 \u043d\u0435 \u0437\u0430\u043c\u043a\u043d\u0443\u0442\u0430) | `E_VALENCE` |\n| SDF \u0431\u0435\u0437 `M  END` | `E_GRAMMAR` |\n| SDF V3000 | `E_UNSUPPORTED` (`V3000_NOT_SUPPORTED`) |\n| `CC.CC.*CC` | `O_POLICY` |\n| `C\\1=C/C=C\\C1` | `OK` (stereo \u043e\u0442\u0431\u0440\u043e\u0448\u0435\u043d, \u0437\u0430\u043f\u0438\u0441\u0430\u043d \u0432 \u043b\u043e\u0433) |\n| 10 000 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0445 \u0441\u0442\u0440\u043e\u043a \u043d\u0430\u0434 \u0430\u043b\u0444\u0430\u0432\u0438\u0442\u043e\u043c SMILES | \u226599% \u0441 \u043d\u0435\u043d\u0443\u043b\u0435\u0432\u044b\u043c \u043a\u043e\u0434\u043e\u043c; \u0434\u043e\u043b\u044f `OK` > 1% \u2192 **\u0442\u0435\u0441\u0442 \u043f\u0440\u043e\u0432\u0430\u043b\u0435\u043d** (\u043f\u0430\u0440\u0441\u0435\u0440 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0442\u0435\u0440\u043f\u0438\u043c) |\n\n\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u2014 anti-leniency control: \u0431\u0435\u0437 \u043d\u0435\u0451 \u043d\u0435\u043b\u044c\u0437\u044f \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0442\u044c, \u0447\u0442\u043e `parse_failure_rate` \u0432\u043e\u043e\u0431\u0449\u0435 \u0447\u0442\u043e-\u0442\u043e \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442.\n\n**4.3 Cross-check SDF\u2194SMILES + \u0435\u0433\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 (\u043f\u0440\u044f\u043c\u043e).** \u0414\u043b\u044f \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 \u043f\u0430\u043d\u0435\u043b\u0438 (\u0433\u043e\u0442\u043e\u0432\u0438\u043c mini-corpus .sdf + .smi, ~13 \u0437\u0430\u043f\u0438\u0441\u0435\u0439) \u0432\u0441\u0435 Tier A-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0442\u044c \u043f\u043e\u0431\u0438\u0442\u043e\u0432\u043e/\u00b1\u03b5. \u042d\u0442\u043e \u0441\u0438\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c **\u043e\u0431\u0449\u0435\u0433\u043e molgraph-\u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430**, \u043d\u043e \u043e\u043d \u043b\u043e\u0432\u0438\u0442 **\u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043f\u0430\u0440\u0441\u0435\u0440\u043e\u0432**. \u0421\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u0430, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u0441 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d (\u043d\u0435\u0432\u0435\u0440\u043d\u043e \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0451\u043d\u043d\u044b\u0439 TPSA-\u043f\u0430\u0442\u0442\u0435\u0440\u043d, \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0430\u0442\u043e\u043c\u043d\u044b\u0445 \u043c\u0430\u0441\u0441, \u043a\u0440\u0438\u0432\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0430\u0440\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438), \u043e\u0431\u0435\u0438\u043c \u0432\u0435\u0442\u043a\u0430\u043c \u043d\u0430\u0441\u043b\u0435\u0434\u0443\u0435\u0442\u0441\u044f \u043e\u0442 \u043e\u0434\u043d\u043e\u0433\u043e \u0438 \u0442\u043e\u0433\u043e \u0436\u0435 \u043a\u043e\u0434\u0430 \u2014 \u0437\u043d\u0430\u0447\u0438\u0442 cross-check \u0435\u0451 **\u043d\u0435 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u0442 \u043d\u0438\u043a\u043e\u0433\u0434\u0430**. \u041f\u043e\u043b\u043d\u043e\u0439 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0435\u0439 \u0441\u0447\u0438\u0442\u0430\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f; \u044d\u0442\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438, \u0430 \u043d\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438.\n\n**4.4 Freeze-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b.** `spec.md`, `controls_panel.csv`, `negative_controls.csv`, `thresholds.json` \u0445\u044d\u0448\u0438\u0440\u0443\u044e\u0442\u0441\u044f (sha256) \u0438 \u043a\u043e\u043c\u043c\u0438\u0442\u044f\u0442\u0441\u044f \u0432 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430. \u041b\u044e\u0431\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u0430 = \u043d\u043e\u0432\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430 \u0441 \u043d\u043e\u0432\u043e\u0439 \u0441\u0442\u0440\u043e\u043a\u043e\u0439 \u0432 changelog; PASS/FAIL-\u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0442 \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438. \u042d\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 \u00ab\u043f\u043e\u0440\u043e\u0433\u0438 \u043f\u043e\u0434\u043e\u0433\u043d\u0430\u043b\u0438 \u043f\u043e\u0434 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u00bb \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u043c\u044b\u043c, \u0430 \u043d\u0435 \u0434\u043e\u0431\u0440\u043e\u0434\u0435\u0442\u0435\u043b\u044c\u044e \u043d\u0430 \u0441\u043b\u043e\u0432\u0430\u0445.\n\n---\n\n## 5. Analysis plan (\u043f\u043b\u0430\u043d, \u0430 \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b)\n\n- **\u0420\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f:** `collections.Counter` + \u0440\u0443\u0447\u043d\u043e\u0439 binning; \u043a\u0432\u0430\u043d\u0442\u0438\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 `statistics.quantiles`; \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u2014 `statistics.fmean/stdev/median`. \u0413\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b: PIL (PNG) \u043b\u0438\u0431\u043e \u0442\u0435\u043a\u0441\u0442\u043e\u0432\u044b\u0435 sparkline; matplotlib \u043d\u0435\u0442.\n- **\u041a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438:** `statistics.correlation` (\u041f\u0438\u0440\u0441\u043e\u043d, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d \u0432 \u0441\u0440\u0435\u0434\u0435) \u043f\u043e \u043f\u043e\u043f\u0430\u0440\u043d\u043e \u043f\u043e\u043b\u043d\u044b\u043c \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f\u043c \u043f\u043e\u0432\u0435\u0440\u0445 SQLite-\u0432\u044b\u0431\u043e\u0440\u043a\u0438; \u0421\u043f\u0438\u0440\u043c\u0435\u043d \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u043d\u0436\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0442\u0435\u043c \u0436\u0435 \u0432\u044b\u0437\u043e\u0432\u043e\u043c; \u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u0434\u043b\u044f {MW, logP, TPSA, HBD, HBA, RB, nRings, charge}. \u041e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 numpy \u2014 \u043d\u0435 \u0431\u043b\u043e\u043a\u0435\u0440: \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e, \u0447\u0442\u043e Pearson/quantiles \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0438\u0437 stdlib.\n- **\u0424\u0438\u043b\u044c\u0442\u0440\u044b:** Lipinski (MW\u2264500, logP\u22645, HBD\u22645, HBA\u226410) \u0438 Veber (TPSA\u2264140 \u00c5\u00b2, RB\u226410) \u2014 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e \u0441\u0442\u043e\u043b\u0431\u0446\u0430\u043c\u0438 `lipinski_violations \u2208 {0..4}` \u0438 `veber_violations \u2208 {0,2}`, \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0443\u043b\u0435\u0432\u043e\u043c \u00ab\u043f\u0440\u043e\u0448\u0451\u043b/\u043d\u0435 \u043f\u0440\u043e\u0448\u0451\u043b\u00bb: \u0434\u043e\u043b\u044f \u00ab0 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439\u00bb \u0438 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0447\u0438\u0441\u043b\u0443 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439 \u043d\u0435\u0441\u0443\u0442 \u0440\u0430\u0437\u043d\u0443\u044e \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e, \u0438 \u0431\u0438\u043d\u0430\u0440\u043d\u0430\u044f \u043c\u0430\u0441\u043a\u0430 \u0432\u044b\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0435\u0451.\n- **\u0413\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438:** group-by \u043f\u043e `source`/`class` (\u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043f\u043e\u043b\u044f) \u2192 \u043c\u0435\u0434\u0438\u0430\u043d\u0430/IQR/\u0434\u043e\u043b\u0438 \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432. \u041f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u043f\u043e\u043b\u044f \u2014 \u043e\u0442\u043a\u0430\u0437 \u043e\u0442 \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0438 \u0441 \u044f\u0432\u043d\u043e\u0439 \u0437\u0430\u043f\u0438\u0441\u044c\u044e, \u0430 \u043d\u0435 \u0432\u044b\u0434\u0443\u043c\u0430\u043d\u043d\u0430\u044f \u0442\u0430\u043a\u0441\u043e\u043d\u043e\u043c\u0438\u044f.\n- **Sensitivity sweep (\u0433\u043b\u0430\u0432\u043d\u043e\u0435 \u043f\u0440\u043e logP).** \u041f\u0440\u0438 MAE logP 0.4\u20130.7 \u043b\u043e\u0433-\u0435\u0434\u0438\u043d\u0438\u0446 \u0434\u043e\u043b\u044f \u043f\u0440\u043e\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f Lipinski **\u0441\u0430\u043c\u0430 \u043f\u043e \u0441\u0435\u0431\u0435 \u0438\u043c\u0435\u0435\u0442 \u0437\u0430\u043c\u0435\u0442\u043d\u0443\u044e \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c**: \u0447\u0430\u0441\u0442\u0438\u0446\u044b \u0432 \u043e\u043a\u0440\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u043f\u043e\u0440\u043e\u0433\u0430 logP\u22485 \u043f\u0435\u0440\u0435\u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043f\u0440\u0438 \u043e\u0448\u0438\u0431\u043a\u0435, \u043c\u043d\u043e\u0433\u043e \u0431\u043e\u043b\u044c\u0448\u0435\u0439, \u0447\u0435\u043c \u0448\u0438\u0440\u0438\u043d\u0430 \u044d\u0442\u043e\u0439 \u043e\u043a\u0440\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u0434\u043e\u043b\u044f \u043f\u0440\u043e\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f **\u043d\u0435 \u0442\u043e\u0447\u043a\u043e\u0439, \u0430 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u043e\u043c**: pass-rate \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438 logP, \u0441\u0434\u0432\u0438\u043d\u0443\u0442\u043e\u043c \u043d\u0430 \u22120.7, 0, +0.7 (\u0438 \u0434\u043b\u044f TPSA \u2014 \u043d\u0430 \u22122 \u00c5\u00b2/+2 \u00c5\u00b2), \u0438 \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442\u0441\u044f \u0440\u0430\u0437\u043c\u0430\u0445 `[lo, hi]`; \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0432\u044b\u0432\u043e\u0434\u0438\u0442\u0441\u044f **borderline density** \u2014 \u0434\u043e\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u0441 logP \u2208 [4.3, 5.7] (\u0438 TPSA \u2208 [138, 142]), \u0442.\u0435. \u0434\u043e\u043b\u044f \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u043e\u0432, \u0432\u043e\u043e\u0431\u0449\u0435 \u043d\u0435\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u0430\u044f \u043a \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0439 \u043e\u0448\u0438\u0431\u043a\u0435 \u043c\u0435\u0442\u043e\u0434\u0430. \u0422\u043e\u0447\u043a\u0430 \u0431\u0435\u0437 \u044d\u0442\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430 \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u043d\u0435 \u043f\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f.\n- **\u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u0434\u0430\u043d\u043d\u044b\u0445:** `parse_failure_rate`, `descriptor_coverage`, `unsupported_share` (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u2014 \u00a72) \u043f\u043e \u0433\u0440\u0443\u043f\u043f\u0430\u043c; \u0431\u0438\u0442\u044b\u0435 \u0437\u0430\u043f\u0438\u0441\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0446\u0435\u043b\u0438\u043a\u043e\u043c, \u0447\u0442\u043e\u0431\u044b \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0431\u044b\u043b\u043e \u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0440\u0443\u043a\u0430\u043c\u0438.\n\n---\n\n## 6. Feasibility\n\n\u0417\u0430\u043c\u0435\u0440\u0435\u043d\u043e \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 (\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0435 \u043c\u0438\u043a\u0440\u043e\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0438, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430):\n- `statistics.correlation` = 0.9993 \u043d\u0430 \u0442\u0435\u0441\u0442\u043e\u0432\u043e\u0439 \u043f\u0430\u0440\u0435; `statistics.quantiles` \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u2192 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u0431\u0435\u0437 numpy \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u0430.\n- \u041f\u043e\u0442\u043e\u043a\u043e\u0432\u044b\u0439 `gzip`+`csv.DictReader`: 200 000 \u0441\u0442\u0440\u043e\u043a \u0437\u0430 0.32 \u0441 \u2192 **~6.3\u00b710\u2075 \u0441\u0442\u0440\u043e\u043a/\u0441** \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u044f\u0434\u0440\u0435, \u0442.\u0435. I/O-\u0441\u043b\u043e\u0439 \u043d\u0435 \u0431\u0443\u0442\u044b\u043b\u043e\u0447\u043d\u043e\u0435 \u0433\u043e\u0440\u043b\u044b\u0448\u043a\u043e; \u0445\u0438\u043c\u0438\u044f \u0434\u043e\u0440\u043e\u0436\u0435 \u0447\u0442\u0435\u043d\u0438\u044f.\n- \u041e\u0431\u0445\u043e\u0434 \u0433\u0440\u0430\u0444\u0430 (BFS + \u0441\u043a\u0430\u043d \u0440\u0451\u0431\u0435\u0440, 25 \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432): **~11 \u043c\u043a\u0441/\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430** \u2192 \u0447\u0438\u0441\u0442\u044b\u0439 \u043e\u0431\u0445\u043e\u0434 \u0434\u0451\u0448\u0435\u0432, \u0434\u043e\u0440\u043e\u0433 \u0431\u0443\u0434\u0435\u0442 \u043f\u0430\u0442\u0442\u0435\u0440\u043d-\u043c\u0430\u0442\u0447\u0438\u043d\u0433 (TPSA/logP/HBD) \u2014 \u043d\u0430 \u043d\u0435\u0433\u043e \u0438 \u0437\u0430\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u043c \u0431\u044e\u0434\u0436\u0435\u0442.\n- `/tmp` = **tmpfs, 1006 GiB \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e**; `/workspace` = NFS, 100% \u0437\u0430\u043d\u044f\u0442, **~2.0 GiB \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e** (write-test \u0443\u0441\u043f\u0435\u0448\u0435\u043d).\n\n**\u041e\u0446\u0435\u043d\u043a\u0430 (\u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e):** \u043a\u043e\u0434 ~1.5\u20133 kLOC \u0447\u0438\u0441\u0442\u043e\u0433\u043e Python (\u043f\u0430\u0440\u0441\u0435\u0440 + \u043f\u0435\u0440\u0446\u0435\u043f\u0446\u0438\u044f + 10 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 + \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430), 2\u20134 \u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u0441\u0435\u0441\u0441\u0438\u0438 \u043d\u0430 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0438 \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438. Runtime \u043d\u0430 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b: \u0437\u0430\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u043c 5\u201320 \u043c\u0441/\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0443 \u043d\u0430 \u044f\u0434\u0440\u0435 (\u043f\u0435\u0441\u0441\u0438\u043c\u0438\u0441\u0442\u0438\u0447\u043d\u043e \u0434\u043b\u044f \u0447\u0438\u0441\u0442\u043e\u0433\u043e Python \u0441 pattern-\u043c\u0430\u0442\u0447\u0438\u043d\u0433\u043e\u043c) \u2192 10\u2075 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u2248 8\u201335 \u043c\u0438\u043d \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u044f\u0434\u0440\u0435, <2\u20135 \u043c\u0438\u043d \u043f\u0440\u0438 8\u201316 \u0432\u043e\u0440\u043a\u0435\u0440\u0430\u0445 (`concurrent.futures`; 224 CPU \u0432 \u0430\u0444\u0444\u0438\u043d\u0438\u0442\u0438, \u043d\u043e \u0431\u043e\u043b\u044c\u0448\u0435 16 \u0432\u043e\u0440\u043a\u0435\u0440\u043e\u0432 \u043d\u0435 \u043d\u0443\u0436\u043d\u043e \u2014 \u0443\u043f\u0440\u0451\u043c\u0441\u044f \u0432 NFS-I/O, \u0430 \u043d\u0435 \u0432 CPU). \u041f\u0430\u043c\u044f\u0442\u044c: \u2264300 MB RSS \u043d\u0430 \u0432\u043e\u0440\u043a\u0435\u0440.\n\n**\u0421\u0442\u0440\u0438\u043c\u0438\u043d\u0433-\u0440\u0435\u0436\u0438\u043c (\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d, \u0431\u0435\u0437 \u043f\u043e\u043b\u043d\u043e\u0439 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430):**\n\u0446\u0435\u043f\u043e\u0447\u043a\u0430 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u043e\u0432 `bytes \u2192 TextIOWrapper(incremental, strict\u2192latin-1) \u2192 csv-rows \u2192 molgraph \u2192 descriptor-tuple \u2192 sqlite batch commit (1000 \u0441\u0442\u0440\u043e\u043a/txn, WAL)`, \u0432\u0441\u0451 \u0441 \u043d\u0435\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u044b\u043c \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c; SDF \u0440\u0435\u0436\u0435\u0442\u0441\u044f \u043f\u043e \u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u0435\u043b\u044e `M  END` \u0438\u043d\u043a\u0440\u0435\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e, \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 slurp'\u043e\u043c. \u041f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u0444\u0430\u0439\u043b\u044b \u2014 **\u0442\u043e\u043b\u044c\u043a\u043e \u0432 `/tmp` (tmpfs)**; \u0432 NFS \u043a\u043b\u0430\u0434\u0443\u0442\u0441\u044f \u043b\u0438\u0448\u044c \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u044b\u0439 spec, \u043f\u0430\u043d\u0435\u043b\u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0439 \u0438 \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0435 \u0441\u0432\u043e\u0434\u043d\u044b\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u044b (\u0431\u044e\u0434\u0436\u0435\u0442 <20 MB \u043d\u0430 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b, \u043f\u0440\u0438 2.0 GiB \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0433\u043e NFS \u2014 \u0441 \u0437\u0430\u043f\u0430\u0441\u043e\u043c). \u042d\u0442\u043e \u0438 \u0435\u0441\u0442\u044c \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 NFS: \u0442\u044f\u0436\u0451\u043b\u044b\u0435 tmp-\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u0442\u0443\u0434\u0430 \u043d\u0435 \u043f\u0438\u0448\u0443\u0442\u0441\u044f \u0432\u043e\u043e\u0431\u0449\u0435.\n\n---\n\n## 7. Limitations / what this design does NOT establish\n\n- **\u041d\u0435\u0442 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 RDKit/OpenBabel/PubChem.** \u0421\u0435\u0442\u0438 \u043d\u0435\u0442, \u0441\u043e\u0444\u0442\u0430 \u043d\u0435\u0442, \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f. \u0412\u0441\u0435 \u00abvs RDKit\u00bb \u2014 \u0430\u043f\u0440\u0438\u043e\u0440\u043d\u044b\u0435 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f, \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u044f.\n- **\u0422\u043e\u0447\u043d\u043e\u0441\u0442\u0438 fallback (\u0432 \u0442.\u0447. MAE logP 0.4\u20130.7, TPSA \u00b11\u20132 \u00c5\u00b2) \u0432\u0437\u044f\u0442\u044b \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b/\u043e\u0446\u0435\u043d\u043e\u043a \u0438 \u0437\u0434\u0435\u0441\u044c \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u044b.** \u0427\u0438\u0441\u043b\u0430 \u043d\u0435\u043b\u044c\u0437\u044f \u0446\u0438\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0440\u0430\u0431\u043e\u0442\u044b.\n- **\u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u0430\u043d\u0435\u043b\u0438** \u2014 \u0442\u0440\u0430\u043d\u0441\u043a\u0440\u0438\u043f\u0446\u0438\u044f; \u0432 \u0441\u0440\u0435\u0434\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430 \u0442\u043e\u043b\u044c\u043a\u043e MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430 (\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430 \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435). \u0422\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 \u0446\u0438\u0442\u0438\u0440\u0443\u0435\u043c\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430.\n- **Cross-check SDF\u2194SMILES** (\u0441\u043c. \u00a74.3) \u043d\u0435 \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0448\u0438\u0431\u043a\u0438, \u043e\u0431\u0449\u0438\u0435 \u0434\u043b\u044f \u043e\u0431\u0435\u0438\u0445 \u0432\u0435\u0442\u043e\u043a; \u044d\u0442\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438, \u043d\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438.\n- **\u041d\u0435\u0442 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043e\u0432, \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0439 \u043f\u0440\u043e\u0442\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f, \u0441\u043e\u043b\u044c\u0432\u0430\u0442\u043e\u0432, \u0441\u0442\u0435\u0440\u0435\u043e\u0445\u0438\u043c\u0438\u0438** (2D-\u0443\u0440\u043e\u0432\u0435\u043d\u044c; stereo \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e). HBD/HBA/RB \u043d\u0430 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043d\u044b\u0445 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0445 \u043c\u043e\u0433\u0443\u0442 \u0440\u0430\u0441\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u0441 RDKit \u0431\u0435\u0437 \u0432\u0441\u044f\u043a\u043e\u0439 \u043e\u0448\u0438\u0431\u043a\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438.\n- **\u041a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d**: \u0444\u043e\u0440\u043c\u0430\u0442, \u043e\u0431\u044a\u0451\u043c, schema, \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0437\u0430\u043f\u0438\u0441\u0435\u0439, \u043d\u0430\u043b\u0438\u0447\u0438\u0435 `source`/`class` \u2014 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b. \u0414\u0438\u0437\u0430\u0439\u043d \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0437\u043e\u0432\u0430\u043d, \u043d\u043e \u043d\u0435 \u0432\u0430\u043b\u0438\u0434\u0438\u0440\u043e\u0432\u0430\u043d \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445; \u0434\u043e\u043b\u0438 `E_UNSUPPORTED` \u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f parse-failure-\u043a\u0440\u0438\u0432\u0430\u044f \u2014 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b.\n- **Tier B-\u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b (logP, acid/base sites) \u043d\u0435 \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u044e\u0442 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 verdict'\u043e\u0432** \u0438 \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u044b \u043f\u043e\u043f\u0430\u0434\u0430\u0442\u044c \u0432 \u043b\u044e\u0431\u044b\u0435 \u00ab\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043c\u043e\u043b\u0435\u043a\u0443\u043b drug-like\u00bb-\u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u0431\u0435\u0437 sensitivity-\u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430; `acid_sites`/`base_site_count` \u2014 \u0441\u0442\u0438\u043f\u0443\u043b\u044f\u0442\u0438\u0432\u043d\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0435\u043d\u0438\u0435.\n- **SSSR-\u0440\u0430\u0437\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u043e\u043b\u0435\u0446** \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u043b\u0438\u0447\u0430\u0442\u044c\u0441\u044f \u043f\u043e tie-break \u043e\u0442 RDKit \u043f\u0440\u0438 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0445 \u0431\u0430\u0437\u0438\u0441\u0430\u0445, \u0445\u043e\u0442\u044f `\u03bc = E\u2212V+C` \u0442\u043e\u0447\u043d\u043e.\n- \u0414\u0438\u0437\u0430\u0439\u043d **\u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442** \u0440\u0430\u0431\u043e\u0442\u043e\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445: \u043e\u043d \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e\u0439 \u0438 \u0447\u0442\u043e \u0435\u0451 \u0433\u0440\u0430\u043d\u0438\u0446\u044b \u043e\u0448\u0438\u0431\u043a\u0438 \u0437\u0430\u0434\u0435\u043a\u043b\u0430\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u044b.\n\n---\n\n## 8. Frozen scope decisions (\u0441 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435\u043c)\n\n1. **pKa \u2014 \u0443\u0434\u0430\u043b\u0451\u043d \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e**, \u043d\u0435 \u00ab\u0441 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439\u00bb. \u041e\u0444\u043b\u0430\u0439\u043d-\u043c\u043e\u0434\u0435\u043b\u0438 \u043d\u0435\u0442; \u0447\u0438\u0441\u043b\u043e\u0432\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u0431\u044b\u043b\u0430 \u0431\u044b \u0446\u0438\u0444\u0440\u043e\u0439, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043f\u0440\u0438\u043c\u0443\u0442 \u0437\u0430 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0443\u044e.\n2. **`acid_sites` / `base_sites` \u2014 \u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u044b**, \u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0443\u0436\u0435 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0433\u043e \u0444\u0443\u043d\u043a\u0446.-\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430 (TPSA- \u0438 HBD-\u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b), \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0438 \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430. \u0415\u0441\u043b\u0438 \u043f\u0440\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0432\u044b\u044f\u0441\u043d\u0438\u0442\u0441\u044f, \u0447\u0442\u043e \u0434\u043b\u044f \u043d\u0438\u0445 \u043d\u0443\u0436\u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430/\u0441\u043b\u043e\u0451\u043d\u0430\u044f \u043b\u043e\u0433\u0438\u043a\u0430 \u2014 **\u043e\u043d\u0438 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f** (\u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0437\u0430\u0440\u0430\u043d\u0435\u0435). \u041e\u0431\u0430 \u043f\u043e\u043b\u044f \u043c\u0430\u0440\u043a\u0438\u0440\u0443\u044e\u0442\u0441\u044f `LOW_CONFIDENCE`, \u043d\u0435 \u0432\u0445\u043e\u0434\u044f\u0442 \u043d\u0438 \u0432 \u043e\u0434\u0438\u043d \u0444\u0438\u043b\u044c\u0442\u0440, \u043d\u0438 \u0432 \u043e\u0434\u0438\u043d PASS/FAIL.\n3. **RB \u2014 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442\u0441\u044f \u0441 \u043c\u0435\u0442\u043a\u043e\u0439 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f**; \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u0441 \u0432\u043d\u0435\u0448\u043d\u0438\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438 \u0442\u0440\u0430\u043a\u0442\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0432\u043e\u043f\u0440\u043e\u0441 \u043a \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438, \u043d\u0435 \u043a\u0430\u043a \u0431\u0430\u0433.\n4. **logP \u0438 TPSA \u2014 \u0432 \u0440\u0430\u0437\u043d\u044b\u0445 \u043b\u0438\u0433\u0430\u0445** (Tier B vs A\u2212), \u0441 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u043c\u0438 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0439.\n5. \u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430\u0445: \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f, \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u043d\u0435\u0442.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0441\u0440\u0435\u0434\u044b (\u043d\u0438\u043a\u0430\u043a\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u043e\u0441\u044c; \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u0432 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435\u0442):\n- `/workspace`: \u0442\u043e\u043b\u044c\u043a\u043e task.json (378 B, JSON); `find / -xdev` \u043f\u043e *.sdf/*.smi/*.mol2/*.smiles \u2192 0 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0439; /data,/datasets,/input,/opt \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442.\n- \u0418\u043c\u043f\u043e\u0440\u0442-\u0442\u0435\u0441\u0442: FAIL rdkit, openbabel, numpy, pandas, scipy, matplotlib, sklearn, pyarrow, networkx, Bio, lxml, svgwrite. OK: yaml 6.0.3, requests 2.32.5, PIL 12.1.1, sqlite3, csv, gzip, json, statistics, graphlib, collections, concurrent.futures, unittest, timeit, multiprocessing, hashlib.\n- Python 3.14.4 (GCC 15.2.0), pip 25.1.1; \u0441\u0435\u0442\u044c \u043c\u0435\u0440\u0442\u0432\u0430: socket pypi.org:443 \u2192 gaierror [Errno -3]; apt \u0431\u0435\u0437 sources.list; wheel-\u043a\u044d\u0448\u0435\u0439 \u043d\u0435\u0442 (\u0442\u043e\u043b\u044c\u043a\u043e /usr/share/python-wheels/setuptools+pip); gcc/g++/make \u0435\u0441\u0442\u044c, \u043d\u043e \u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043d\u0435\u0447\u0435\u0433\u043e \u2192 \u0434\u043e\u0432\u043e\u0434\u043a\u0430 RDKit \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430.\n- statistics \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 correlation/linear_regression/quantiles/fmean/stdev \u2192 \u041f\u0438\u0440\u0441\u043e\u043d \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0431\u0435\u0437 numpy: \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u043b\u0430\u043d \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c (\u0437\u0430\u043c\u0435\u0440\u0435\u043d\u043e: correlation=0.9993 \u043d\u0430 \u0442\u0435\u0441\u0442\u043e\u0432\u043e\u0439 \u043f\u0430\u0440\u0435).\n- \u041c\u0438\u043a\u0440\u043e\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a I/O: gzip+csv.DictReader, 200 000 \u0441\u0442\u0440\u043e\u043a \u0437\u0430 0.32 \u0441 \u2248 6.3\u00b710\u2075 \u0441\u0442\u0440\u043e\u043a/\u0441/\u044f\u0434\u0440\u043e.\n- \u041c\u0438\u043a\u0440\u043e\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a \u0433\u0440\u0430\u0444\u0430: BFS+edge scan \u043d\u0430 \u0433\u0440\u0430\u0444\u0435 \u0438\u0437 25 \u0442\u044f\u0436\u0451\u043b\u044b\u0445 \u0430\u0442\u043e\u043c\u043e\u0432 \u2248 11 \u043c\u043a\u0441/\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 (20 000 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432).\n- \u0424\u0430\u0439\u043b\u043e\u0432\u0430\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u0430: /tmp \u2014 tmpfs 1006 GiB \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e; /workspace \u2014 NFS 100% \u0437\u0430\u043d\u044f\u0442, ~2.0 GiB \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e, \u0437\u0430\u043f\u0438\u0441\u044c \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430 (write-test). \u041e\u0442\u0441\u044e\u0434\u0430 \u043f\u0440\u043e\u0435\u043a\u0442-\u0440\u0435\u0448\u0435\u043d\u0438\u0435: tmp-\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u0432 tmpfs, \u0432 NFS \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u0438 \u0441\u0432\u043e\u0434\u043a\u0438.\n- \u0420\u0435\u0441\u0443\u0440\u0441\u044b: nproc=224, sched_getaffinity=224, MemTotal \u22482.06 TB.\n- MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430 \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u043e\u0439 \u043f\u0430\u043d\u0435\u043b\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u043d\u0430 \u0432 \u0441\u0440\u0435\u0434\u0435 \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u043e\u0439 \u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435 \u0441\u043e \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u043c\u0438 \u0430\u0442\u043e\u043c\u043d\u044b\u043c\u0438 \u043c\u0430\u0441\u0441\u0430\u043c\u0438 (ethanol 46.069, aspirin 180.159, caffeine 194.194, glucose 180.156, ibuprofen 206.285, nitrobenzene 123.111, ATP 507.182) \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u0430\u044f \u0432 \u0434\u0430\u043d\u043d\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u0447\u0430\u0441\u0442\u044c \u043f\u0430\u043d\u0435\u043b\u0438; TPSA/HBD/HBA/RB \u2014 \u0442\u0440\u0430\u043d\u0441\u043a\u0440\u0438\u043f\u0446\u0438\u044f \u0438\u0437 \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432, \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430.\n- \u0417\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e, \u0447\u0442\u043e \u043d\u0438 \u043e\u0434\u0438\u043d \u0438\u0437 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0445 \u043c\u0438\u043a\u0440\u043e\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u0432 \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u043c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043f\u043e \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044e \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u044b\u0445 \u0441\u0432\u043e\u0439\u0441\u0442\u0432; \u044d\u0442\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u0432.", "assumptions": ["\u0414\u0430\u0442\u0430\u0441\u0435\u0442 \u0442\u0430\u043a \u0438 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c): \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0437\u043e\u0432\u0430\u043d \u043f\u043e \u0444\u043e\u0440\u043c\u0430\u0442\u0443 \u0432\u0445\u043e\u0434\u0430, \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u2014 \u043d\u0430 \u043a\u0443\u0440\u0438\u0440\u0443\u0435\u043c\u043e\u0439 \u043f\u0430\u043d\u0435\u043b\u0438 \u043a\u0430\u043a \u0447\u0430\u0441\u0442\u0438 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438", "pKa \u0438\u0441\u043a\u043b\u044e\u0447\u0451\u043d \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e; acid_sites/base_sites \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u043f\u043e\u0431\u043e\u0447\u043d\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0443\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u043e\u0433\u043e \u0444\u0443\u043d\u043a\u0446.-\u0433\u0440\u0443\u043f\u043f\u043e\u0432\u043e\u0433\u043e \u043c\u0430\u0442\u0447\u0435\u0440\u0430, \u0438\u043d\u0430\u0447\u0435 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f", "\u0421\u0440\u0435\u0434\u043d\u0438\u0435 (\u043d\u0435 \u043c\u043e\u043d\u043e\u0438\u0437\u043e\u0442\u043e\u043f\u043d\u044b\u0435) \u0430\u0442\u043e\u043c\u043d\u044b\u0435 \u043c\u0430\u0441\u0441\u044b; \u0443\u0440\u043e\u0432\u0435\u043d\u044c 2D: \u0431\u0435\u0437 \u0442\u0430\u0443\u0442\u043e\u043c\u0435\u0440\u043d\u043e\u0439/\u043f\u0440\u043e\u0442\u043e\u043d\u043d\u043e\u0439/\u0441\u043e\u043b\u044c\u0432\u0430\u0442\u043d\u043e\u0439 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u0441\u0442\u0435\u0440\u0435\u043e\u0445\u0438\u043c\u0438\u044f \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f", "RB \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442\u0441\u044f \u0441 \u044f\u0432\u043d\u043e\u0439 \u043c\u0435\u0442\u043a\u043e\u0439 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f (strict, amide-excluded); \u00ab\u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u043e\u0433\u043e\u00bb \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f RB \u043d\u0435\u0442", "\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f TPSA/HBD/HBA/RB \u0432 \u043f\u0430\u043d\u0435\u043b\u0438 \u0438 \u0432\u0441\u0435 \u0446\u0438\u0444\u0440\u044b \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438 \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0435 (\u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0430/PubChem-\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e), \u0432 \u0434\u0430\u043d\u043d\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f; \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u0430 \u0442\u043e\u043b\u044c\u043a\u043e MW-\u043a\u043e\u043b\u043e\u043d\u043a\u0430", "\u041a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 5\u201320 \u043c\u0441/\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u0430 \u043d\u0430 \u044f\u0434\u0440\u043e \u2014 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u043b\u044f \u0447\u0438\u0441\u0442\u043e\u0433\u043e Python \u0441 pattern-\u043c\u0430\u0442\u0447\u0438\u043d\u0433\u043e\u043c, \u0430 \u043d\u0435 \u0437\u0430\u043c\u0435\u0440", "\u0410\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0439 (spec/\u043f\u0430\u043d\u0435\u043b\u0438/\u043f\u043e\u0440\u043e\u0433\u0438) \u0445\u044d\u0448\u0438\u0440\u0443\u044e\u0442\u0441\u